INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (23, 5, '五、“给定资料3”引用了《论语》中的话：“不学礼，无以立。”请以这句话为中心议题，联系社会现实，自拟题目，写一篇文章。（35分）
