INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (26, 2, '二、假如你是随团秘书，请根据“给定资料2”，把代表团团长的考察笔记，归纳整理为一份《国外城市水系建设考察报告》提纲。（15分）
