INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (26, 4, '四、“给定资料4”介绍了G市某些区县在实施“水生态+扶贫”模式过程中取得的成效等内容。假如你是G市人大代表，准备提交一份“关于在全市推广‘水生态+扶贫’模式的建议”。请根据“给定资料4”，拟定提出推广“水生态+扶贫”模式的理由和可推广的相关措施。（20分）
要求：
（1）紧扣资料，内容具体；
（2）理由充分，措施明确；
（3）层次分明，有逻辑性；
（4）不超过500字。', 20, 500, '4、完善监测体系，重视建立和健全各种监测网站。【⑪监测体系】');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (26, 5, '五、参考给定资料，以“以水为师”为题，联系实际，写一篇文章。（40分）
要求：
（1）见解明确、深刻；
（2）参考“给定资料”，但不拘泥于“给定资料”；
（3）思路明晰，语言流畅；
（4）总字数1000～1200字。
2017年国考公务员考试《申论》省部级卷（解析）', 40, 0, '5、加强国家之间和地区之间的合作。【⑦合作交流】
参考答案一：
水最突出的特性是柔。儒的本义也是柔，“儒之柔”代表中国文化性格的弱德之美，体现为耐心、等待、忍耐、弹性、柔顺等品性，他们不是软弱无力，废弃一切作为，而是柔中带刚。
通过水的意象能够更好的理解儒家文化的内涵。第一，水不定形、善于变化，确立了儒家存在论的基本意象，符合“道”的品格，让人们领会“道”的内涵；第二，水蕴含善良、柔弱、滋养万物、不争夺等特性，奠定了儒家道德论的基本取向，凸显道德的品性，透露出中国文化的传统性格。
“儒之柔”对中国影响深远。它使中国不受外界危机影响，克服动乱；影响中国人同自然界、同他人打交道的方式；影响中国古典技术的文化性格和文化取向，使其不具有进攻性和侵略性。
参考答案二：');
INSERT INTO shenlun_paper (id, paper_code, title, year, version, question_count) VALUES (27, '2018-fs', '2018年国家公考《申论》真题（副省级）', 2018, '副省级', 1);
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (27, 1, '材料1', '1.本题本由给定资料与作答要求两部分构成。考试时限为180分钟。其中，阅读给定资料参考时限为50分钟，作答参考时限为130分钟。
2.请在题本、答题卡指定位置上用黑色字迹的钢笔或签字笔填写自己的姓名和准考证号，并用2B铅笔在准考证号对应的数字上填涂。
3.请用黑色字迹的钢笔或签字笔在答题卡上指定的区域内作答，超出答题区域的作答无效！
4.待监考人员宣布考试开始后，方可开始答题。
5.所有题目一律使用现代汉语作答。未按要求作答的，不得分。
6.监考人员宣布考试结束时，应立即停止作答，将题本、答题卡和草稿纸都翻过来留在桌上，待监考人员确认数量无误、允许离开后，方可离开。
严禁折叠答题卡!
二、给定材料');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (27, 2, '材料2', 'N市为推动“中国制造2025”试点示范城市在本地落地实施，组成调研组对本市制造业情况进行了调研。下面是调研所形成的材料。
●我市已经基本形成了比较完备的智能制造政策框架体系，智能制造试点示范工作稳步推进，智能制造创新平台和核心技术突破初见成效，龙头企业智能化转型和区域集聚加快形成，以工业机器人为引领的智能制造装备产业发展驶入“快车道”。可以说，在以智能制造为重心的方略下，智能经济之“核”初步形成。但仍面临问题和不足：智能制造的基础有待夯实，物联网、云计算和大数据等基础性关键环境要素的建设滞后于智能制造发展需求。其中，智能制造装备缺“核”少“芯”问题最为突出，核心控制技术依赖进口，工业机器人等智能制造核心产业研发投入大部分仍处于实验室阶段。这导致了我市智能经济发展过程中存在着示范引领有待加强、智能制造标准指数缺位、国际技术合作服务乏力等诸多亟待解决的难题。
“要推进强基工程，打通智能制造承载能力的‘卡口’。”调研组建议，要瞄准关键基础材料、核心基础零部件、先进基础工艺和产业技术基础的“四基”短板，着力在新材料、智能装备、新一代信息技术等重点领域的“四基”工程化、产业化生产和应用上取得突破；要通过培育一批行业细分领域的“工匠型”企业，积极采用新技术、新工艺、新设备、新材料，促进“产品”向“精品”转变，并积极参与行业标准制订，形成一批能够代表“N市智造”、引领国内产业发展的技术标准。
●传统产业是我市目前经济发展的主要支柱，占全市规模以上工业总产值的比重超过70%，是我市经济整体转型升级的主战场，更是智能制造推广应用的大市场。
调研中发现，在东南亚国家低成本吸引力和发达国家制造业回归双面夹击下，我市传统产业渴望通过智能化改造提升生产效率、产品品质、增强盈利能力的内生需求十分强烈。市委市政府也适时地把传统产业智能化改造列为建设“中国制造2025”试点示范城市的主要任务；建立了N市智能制造产业研究院，在全国率先成立智能制造协会。具有示范意义的项目也在不断涌现。传统产业智能化改造的动力很强、基础扎实。
但数据显示：全市7300多家规模以上工业企业中实施智能化改造的比例不到30%，部分中小企业尚未开展智能化改造。调研组认为，对于实施智能化改造，传统产业的绝大多数企业主存在不懂、不敢、不愿三种态度，主体意识并不强。同时，智能化改造的核心技术发展滞后、系统集成供给不足、人才和网络基础设施支撑有待加强等问题，也延缓了传统产业智能化改造的步伐。
推进传统产业进行智能化改造，就要引导创新协同，构建最大限度发挥大中小微企业、产学研用各方优势的协同创新创业共同体，集中攻克一批以软硬件一体化为主要特征、带动性强的智能装备，自主培育扶持一批具有很强市场竞争力的系统集成、装备研制、软件开发与智能制造新模式应用等领域的智能装备骨干企业。要开展试点示范，在化工、汽车、纺织、家电、机械制造等重点行业中开展智能化改造示范应用，培育一批“专精特新”的“工匠型”企业。
●生产性服务业是智能制造发展的推动力，而我市在这方面发展相对滞后，成了发展“瓶颈”之一。当前我市生产性服务业规模小、结构差等问题依然突出，主要表现在：制造企业普遍不能接受生产性服务外包这种模式，导致其发展迟缓；生产性服务业“重硬轻软”，重视工艺技术服务而轻视管理、市场、人才服务；缺乏本土的全国性生产性服务企业；服务资源整合共享机制尚未建立。
要加快谋划新增关键生产性服务业集聚平台，如把电商经济创新园区建成“N市定制制造和定制电商生产性服务业集聚区”，整合现有制造业服务平台，建设“N市生产服务业综合对接平台”等。要大力推进企业内生产性服务建设，积极鼓励制造业企业成立生产性服务业公司，培育企业研究院和工程技术中心。要大力培育智能制造生产性服务龙头企业，重点引进和培育引领性智能制造系统集成服务商、全国性的制造工业设计服务商，建立生产性服务应用技术创新联盟。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (27, 3, '材料3', 'W市多次举办了中国机器人峰会。人工智能等流行词汇在这里不是抽象的概念，而是触手可及的现实。W市民营经济发达，但传统产业占比超过70%。这样一个传统制造业占大头的县级市，经济转型升级的突破口在哪儿？W市的探索表明，发展智能经济或许是关键之招。
第四届中国机器人峰会开幕前夕，记者深入W市的工业园区、企业生产车间，探寻和领略这座城市关于智能制造的雄心。
在平板电脑上用手指点击一个程序发出指令，只见一个身材高大的机器人，灵巧地挥舞着手臂，利索地把几个玻璃杯叠放在一起，成了金字塔状。这是智能制造产业研究院以G为首的团队最新研发的双臂柔性机器人，也是国内自主研发的首个十四轴双臂机器人。
在W市，人们意识到，在智能经济这一新形态下，谁能在智能机器人这一先导产业捷足先登，谁就能抢占先机。因而，W市明确把机器人产业作为发展智能经济的切入点。
在W市采访，记者接触到的专家和企业家，均对即将开幕的中国机器人峰会充满期待。这个业内盛会对W市机器人产业的发展拉动作用明显。智能制造产业研究院的迅速成长，以及随后一系列机器人企业的落户，正是W市花大力气举办中国机器人峰会结出的果实。
中国机器人峰会，只是W市布局机器人产业和智能经济的“冰山一角”。W市有关负责人表示，该市发展机器人产业的一系列规划，并不是一时兴起的跟风，而是区域发展战略的延续和深化。W市是经济强市，制造业基础较好，应用市场广阔，发展机器人产业可谓水到渠成。
除了中国机器人峰会、智能制造产业研究院，W市还在规划建设机器人小镇。眼下，一个拥有机器人产业制造基地、机器人产业学院、机器人展览交易市场的机器人小镇正拔地而起。目前小镇已落户智能经济项目21个，投资7.2亿元。
机器人以及智能经济的魅力，不仅在其本身作为新的经济增长点，更在“牵一发而动全身”的强大带动力——机器人是产业结构调整升级的突破口和助力器。
一条自动化流水线上，近20个大大小小的配件经过自动组装、检测，成为一个个喷头，这是记者日前在某自动技术有限公司看到的生产场景。这套生产线是为W市一喷雾器企业量身定制的，平均每分钟可生产60多个喷头，节省劳动力40人至60人。
喷雾器制造是W市的一大“块状经济”，随着人口红利逐渐消失，“机器换人”在业内广受青睐。
在经信局局长的案头，摆着一份长长的企业名单，那是W市传统企业智能化改造的进度表。传统企业借助“机器换人”进行自动化、智能化改造已形成高潮。记者了解到，2016年度W市以“机器换人”为突破口，组织开展“机器换人”重点专项182项，项目总投资21.06亿元，实现企业核心生产设备工序（工位）减员8411人，人均产值提高3倍以上。
不仅通过“机器换人”减少人员、提升效率，还要基于物联网技术，用数据建模，用大数据分析的方法，为产品生产找到一个最合适、成本最低的制造模式。
在另一家公司的实验车间，记者看到两个机械手根据不同的零部件，自如地切换10余套夹具，协同完成一个精密产品的组装。整条流水线上机器人的所有操作都是通过后台管理系统的精密测算来指示的，设备生产系统和业务管理系统无缝衔接。
从模仿到跟随，再到自主创新，近年来W市涌现出一大批本土的系统集成和服务提供商，服务于传统制造业的升级改造。
高端人才的多少，在一定程度上决定了一个地方产业的发展走向。然而，对一个县级市而言，吸引高端人才并不容易。一个人带来一个产业，这句话是W市引才工作的生动写照。10多年前，辞去国外公司高管职位的L带着技术和人才来到W市。在L的带领下，当年年底，该市第一块靶材产品成功下线，这意味着中国结束了溅射靶材完全依赖进口的历史。
G是自动化领域全球首席科学家。虽然来到W市的时间不长，但他发挥自己的聪明才智，在全球范围内网罗智能领城的高端人才，目前已引进机器人领域国家“千人计划”专家18名，创办相关企业14家，让机器人“块状经济”在W市初具雏形。
欲致奇效，必出奇招。现如今，各地都在寻找经济转型升级的路径。但培育智能经济，打造机器人产业，寻常路径很难起到效果。单就引进人才一条，如果没有政府层面大手笔推动，单凭企业的力量难免捉襟见肘。因而，政府的“有为之手”至关重要。
在W市，地方政府通过筑巢引凤，吸引海内外各类创新基因集聚，并辅以相应的生态，促进其相互碰撞、发酵，产生“化学反应”。在W市，企业家之间、企业家和政府之间这种密切的互动，让企业成长多多。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (27, 4, '材料4', '日前，“D市杯”国际工业设计大奖赛举行了颁奖典礼，共有海内外20多项设计从3000多件参赛作品中脱颖而出，拿下各项大奖。
D市共举办了11届国际工业设计大赛。本届大赛更突出了设计资源与产业对接，开展了设计师对接会、工业设计成果展等系列活动，共征集到参赛作品3255件，最后评出概念组金奖1名、银奖3名、铜奖6名，以及产品组金奖1名、银奖3名、铜奖6名。
一位教师此次拿到概念组金奖。这是一组适合中国人烹饪习惯的智能炊具，名为“美味中国”。“中国人烹饪讲究火候，蒸鱼是蒸五分钟还是八分钟？这个时间往往不好把握，但温度可以最直观体现。”这个锅的最大秘密是手柄一按就可以分离，能自动检测锅内温度，不会让蒸煮、炒菜出现“口感太老”“偏生”等问题。这位教师称，这个手柄未来甚至可以与普通的蒸锅、电磁炉等搭配，市场空间非常大，相比于概念复杂、功能冗余的各种智能化产品，这种简单而实用的设计才能真正改变生活。而产品组金奖作品是一套沙发，这套沙发的设计体现多功能，拼接组合适应各种户型。
现场众多专家认为，D市年年举办工业设计大赛，品牌效应已经很强，吸引了国内外越来越多的年轻设计师关注，不少实用化、智能化的工业设计，堪称惊艳，这是一笔有待进一步挖掘的宝贵财富。
“现在，已经不是科技推动设计的时代，而是设计推动科技的时代。”此次设计创新高峰论坛上，著名设计顾问H教授做了主题演讲，谈到了作为典型的工业大市，D市要学会用设计推动技术创新、产品创新，借用人的“慧”，打造物的“智”，将工业技术和设计创新深度融合。H认为，好的设计师应该思考满足人们的实际需求，改善人的生活质量。而更高明的设计师，则要关注人类，关注生存环境，应该思考人与产品、与大自然的关系。谈到中国设计的发展，H指出，中国的设计师应该多研究吸收中国人的传统文化，比如在设计中国的传统建筑或家具时，应该更多地去中国传统文化中寻找灵感。这并不意味着在一个现代物品上印几个传统图案就行了，而是要真正去体味中国传统文化蕴含的智慧和美。
工业设计协会的Y教授说，此次获奖作品很多都是智慧生活类产品的设计，这构成了工业设计的一种方向。中国如今的产品从外观和结构设计上已经不错了，可以说是“四肢发达”“体格健壮”，有很好的基础，但就是缺点儿“脑子”，也就是智能化水平较低。现在迫切需要的就是往这些健壮的铁疙瘩身上植入“大脑”。智能化、交互化成为人类生活的必须，也成为工业设计的关键词。比如，我们开发了一个核心智能化系统，叫作“多行业嵌入式技术”。拥有了这种核心技术，再通过合理的设计，加上不同的外壳，就可以把它变成割草的、扫地的、清洗游泳池的全自动机器。只要你想得到，它甚至可以装到任何产品当中去。这就是服务创新的发展方向。服务设计就是数字化与用户体验的交互，就是在产品中融入时间、情感等因素。未来真正的“智造”，一定需要智能化、交互化的工业设计。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (27, 5, '材料5', '以下是专家意见摘录。
人类经过了农业时代，工业时代，进入了现在的互联网时代，接下来的时代应该是“想象力经济时代”。设计师将是那一个时代的主人。
2016年，一场以“创造不可能”为主题的全球创新设计大会走入了人们的视野。数十位设计大咖通过对时代痛点与未来发展趋势的解读与畅想，让我们第一次了解了“新物种”“爆款计划”以及“想象力经济”这些概念中隐含的巨大价值。中国领先的创新设计平台，则以“众创”的模式推动想象力向生产力转化，致力于用设计创造更多经济价值。
这里面所体现的“共享设计”的理念，激发了个人创造力的觉醒，并由此引领设计新风潮。这一全新理念，意在打造一个集企业、用户、设计师为一体的共享生态圈，同时将设计上升到了一个“众创”的维度，赋予每个参与者以创造者和受益者的双重身份，由此推动想象力的价值链实现最大化的延展。
让想象力产生价值乘数效应，这正是“众创”所希望的结果。共享价值的实现，激发了更多人加入共享设计生态圈。
设计师可以通过与用户进行交流汲取全新的创意灵感，与企业沟通将设计转变为惠及大众的创新产品。企业家也有了机会向用户展现自身的创意产品，聆听他们的想象进而洞察他们的需求，让具有创造力的设计师助力企业的产品创新，进而创造更大的商业价值。
当用户需求被设计师解读，并对产品进行重新创作，优秀的产品便产生了，这个产品再造并走向市场形成商业价值的过程，就是想象力经济的落地体现。想象力经济的本质正是将人的创新精神转化为商业价值的一个过程。
想象力是消费升级的原动力，消费升级反映了消费水平和发展趋势，让消费者为内心的归属感买单，其突破口在于找到消费者真正的欲求。
每个时代都会出现某种经典产品来推动社会的发展和变革，互联网时代的是手机、电脑等终端产品，智能时代的是智能机器人。智能机器人普及后，对人类来说，想象力将会成为下一个时代的主导，设计师将成为推动社会进步的重要力量。
互联网技术的进步使万物产生共联，共享经济的产生让社会资源得到优化配置。个体创造力的连接与共享是想象力经济发挥价值的基础。个人创造力的觉醒、企业创新力的横空出世推动想象力成为未来经济发展的新驱动力。而创造力共享让每一个天马行空的创意设计变现，从而创造更多颠覆时代的爆款产品，充分挖掘设计师个体的价值。
只要拥有想象力，敢于创新，就有可能迎来想象力经济的时代。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (27, 6, '材料6', '有学者认为：“人最伟大的特点和优势不只是会学习，关键在于富有想象力，具有穿越未来的能力。”爱因斯坦曾经说过：“想象力比知识重要。”
想象力是人类所特有的一种天赋。想象力是在已有形象的基础上，在头脑中创造出新形象的能力。想象力也是一种创造力。培养想象力并非要抛弃知识，而是相反，需要更多元、更丰富、更深远的知识集群。
人工智能技术正在不断推动移动互联网形态完成新变化，完成更自主的信息捕捉，更智慧的分析判断。然而人工智能无论如何先进，终究无法超越人类的审美和想象力，无法超越每一个人呼之欲出的创造能动性。
从某种意义上说，在浩如烟海的知识网中，科学、艺术和古文化对于想象力都起着非常重要的作用，构成了想象力的源泉。
提出了“证伪主义”的波普尔，在科学认识上刷新了人类的认识：敢于批判，不断质疑，是科学精神的核心。这和传统的科学认知“科学是经验积累的产物，被证明或者被无数次重复验证的科学理论就是永远正确的”，很不一样。
艺术，作为代表美的精神力量，贯穿于人类发展的全时空。有了它，人类可以无止境地向着无限美丽的世界前进。
历经多少世纪而留存下来的古文化，蕴含着需要想象力才能充分挖掘的惊人智慧和秘密，它是保持想象力永不枯竭的源泉。不少思维活跃的前沿科学家都是人类学和古文化的爱好者。他们研究的科学决然不是宗教，但是，他们比任何人都敏感于那些古老民族的神秘文化和宗教，并从中大量汲取了养分。
而中国人的想象力则更有自己文化传统的优势可以依托，中国人的古典文学和传统艺术催生了一代代中国人的东方式灵感，庄周的梦蝶，屈原的《天问》，敦煌的飞天，李白心中的皓月……，都蕴含着值得中国人真正去体味的传统文化的智慧和美。
这样的例子还有很多，几乎每一个当代在创新领域有所建树的人，都可以捕捉到他们从科学、艺术和古文化中汲取想象力的痕迹。然而，想象力并不独为创新者所占有，在平凡的生活中，想象力能给每一个人以幸福感。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (27, 3, '三、作答要求
根据“给定资料1”，对调研组的调研材料，从成绩、问题和建议三方面进行概述。（15分）
要求：
（1）准确、全面；
（2）恰当提炼，条理清晰；
（3）不超过350字。
上级部门来W市考察，请你根据“给定资料2”，就W市在经济转型升级过程中的探索，写一份汇报提纲。（20分）
要求：
（1）紧扣资料，内容具体；
（2）语言流畅，有逻辑性；
（3）不超过400字。
根据“给定资料3”，请你对划线句子“借用人的‘慧’，打造物的‘智’”加以分析。（15分）
要求：
（1） 观点明确，紧扣资料，有逻辑性；
（2）不超过300字。
根据“给定资料4”，谈谈你对“想象力经济”的理解。（10分）
要求：
（1）准确、全面。
（2）不超过200字。
请深入思考“给定资料5”划线句子“科学、艺术和古文化对于想象力都起着非常重要的作用，构成了想象力的源泉”，自拟题目，自选角度，联系实际，写一篇文章。（40分）
要求：
（1）观点明确，见解深刻；
（2）参考“给定资料”，但不拘泥于“给定资料”；
（3）思路清晰，语言流畅；
（4）字数1000～1200字。
2018年国家公考《申论》真题（副省级）（解析）', 15, 350, '');
INSERT INTO shenlun_paper (id, paper_code, title, year, version, question_count) VALUES (28, '2018-ds', '2018年国家公考《申论》真题（地市级）', 2018, '地市级', 1);
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (28, 1, '材料1', '1.本题本由给定资料与作答要求两部分构成。考试时限为180分钟。其中，阅读给定资料参考时限为50分钟，作答参考时限为130分钟。
2.请在题本、答题卡指定位置上用黑色字迹的钢笔或签字笔填写自己的姓名和准考证号，并用2B铅笔在准考证号对应的数字上填涂。
3.请用黑色字迹的钢笔或签字笔在答题卡上指定的区域内作答，超出答题区域的作答无效！
4.待监考人员宣布考试开始后，方可开始答题。
5.所有题目一律使用现代汉语作答。未按要求作答的，不得分。
6.监考人员宣布考试结束时，应立即停止作答，将题本、答题卡和草稿纸都翻过来留在桌上，待监考人员确认数量无误、允许离开后，方可离开。
严禁折叠答题卡!
二、给定材料');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (28, 2, '材料2', '位于R市郊西隅的沙坝村，总面积约10平方千米，山清水秀，历史悠久。
1980年前后，家庭联产承包责任制开始在中国广大农村推行。中共中央《关于加快农业发展若干问题的决定》《关于进一步加强和完善农业生产责任制的几个问题》等有关“包产到户”“包干到户”的文件一层层传达下来，但沙坝村却没有变革的迹象，人们还在观望。时任大队书记的杨某回忆说：“那时候土地、山林还有各种财产都是国家（集体）的，国家的东西，哪个敢随便动！”
到了1981年底，沙坝村把耕地按好、中、差进行了搭配，然后按人口平均发包给村民，完成“分田到户”，第一轮家庭联产承包责任制在沙坝村初步落实。从此，在土地所有权不变的情况下，村民对于承包地有了经营权、使用权。当时的规定是：所有承包地土地，不许出租、买卖；不许在承包地上建房、烧砖瓦等。虽然承包时大队已经确定承包期是3至5年，但是，村民中仍有人怀疑分田到户不长久，会不会“今天分下去，明天又收回来”。直到1984年的中央一号文件提出“土地承包期一般应在十五年以上”，村民们的忧虑才初步解除。而后中央提出的“为了稳定土地承包关系，鼓励农民增加投入，提高土地的生产率，在原定的耕地承包期到期之后，再延长三十年不变”，算是给农民吃了“定心丸”。为了给农民稳定的土地承包经营预期，党的十九大报告明确提出“保持土地承包关系稳定并长久不变，第二轮土地承包到期后再延长三十年”。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (28, 3, '材料3', 'L村位于某省中北部沿海平原区，粮食作物以小麦、玉米为主，冬小麦与夏玉米一年两季轮作，经济作物以苹果为主。L村的土地分为两类，一是“围庄地”，在村庄周边，有较好的水利条件；二是“洼子地”，离村庄远，水利条件较差。与全国大多数村庄一样，L村也在20世纪90年代中后期根据当时的政策完成了“二轮土地承包”。L村把全村土地分成两份，一份为各户承包的人口地；另一份为机动地。机动地主要用于给新增加的人口增地。
与其他村庄二轮承包普遍执行的“增人不增地，减人不减地”的土地政策不同的是，L村在机动地上实行“增人增地但减人不减地”的办法。自二轮土地承包以来，L村的人口增减变化将近百人。L村给新增加的人口分配土地先从位置、水利条件较好的围庄地开始，围庄地分完之后，新增加的人口就只能分到洼子地了。到了2014年，预留的机动地全部分配完了，“增人增地但减人不减地”的办法也就难以为继了。
村民李某在二轮承包时家里只有他们夫妇和未成年的儿子，多年后儿子娶妻生子，都没赶上村里分地，一家6个人种着3个人的地，收入窘迫。特别是每当看到邻居张某家2个人种着9个人的地时，颇有怨言：“明显不公平，就应收回重分。”但张某对他的话却不完全认同：“我家地多人少是事实，可二轮续包的时候就是这样，30年不变也是国家规定的。”
与李某、张某想要地、想种地不同，L村还有不想要、不想种地的人。76岁的万老汉，家里有6亩地，儿子和孙子都在外地打工、上学。每年的秋收季节都是万老汉最发愁的时候，繁重的劳动都得雇人帮忙。他想把地流转出去，但因为地比较零散，收益也不高，流转也很困难。村里和万老汉情况差不多的还有二十多人。近几年一直在外地打工的王某说：“种地费时费力不说，农忙时回家打理，请假还要被扣工资，不合算。这两年一直是托付亲戚来种地，没什么收益，明年也不想这么干了。”此外，村里还有10户完全脱离农业的家庭，因各种原因，他们承包的土地大多撂荒了。
现任村支书告诉记者说，村里二轮承包后一直没进行土地调整，这是因为国家对土地调整有政策，明确提出“小调整、大稳定的前提是稳定”。“小调整”的间隔期最短不得少于5年，而且“小调整”只限于人地矛盾突出的个别农户。2006年因为村民的承包地占用量与家庭人口不均衡，村里曾有过一次调整的打算，村委会研究决定：凡是人口减少以及已经迁往城镇落户的农户，其承包的土地份额一律收回，另行发包给新增人口的农户。村民石某因妻子去世而被收回了2亩地。石某不服，将村委会告上法庭，要求返还被收走的土地。法院经审理认为，2003年实施的《农村土地承包法》确立了“承包土地以户为单位，减人不减地”的原则。根据该法律，家庭承包经营权的主体是农户整体，而不是家庭成员个体。只要承包方的家庭还有人在，土地就是不能收回。只有在承包经营的家庭消亡，或承包方全家迁入设区的市并转为非农户口的情况下，发包方才可以收回承包地。如果承包方自愿放弃承包地，则应提前半年提出申请。最后法院判决村委会返还石某土地。石某这一告，那次土地调整就没往下进行。后来，国家对土地调整的限制越来越严格，多次强调“承包期内，发包方不得调整承包地”“现有土地承包关系要保持稳定并长久不变”。
2016年春，李某和一些农户以土地承包量有失公平为由找到了当地政府，要求调整。这一诉求得到了政府的支持。面对这种局面，村支书无奈地说：“这样一来，我们的压力很大，看来村里的土地调整也不是一个简单的事。”');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (28, 4, '材料4', '据有关部门统计，到2016年年底，中国大陆城镇常住人口已达7亿9298万，比2015年末增加2182万人，城镇人口占总人口比例为57.35%。随着中国城市化进程的加快，大量农村人口涌入城市。
李奶奶是几年前从农村来到X市的。离开了广袤无垠的田野，住进了层层叠叠、密密麻麻单元楼的瑞丽花园小区。舒适的住所、单调的生活、陌生的邻里，李奶奶过得并不开心，觉得自己被压得“喘不过气来”，她几乎每天都要坐公交车穿过喧闹的街区到城郊的公园里活动活动筋骨，想法子找人说说话。
瑞丽花园小区是X市近年来新开发的商品房小区，位于市区两大主要交通干线的交汇处。因位置临近商业中心，地价昂贵，住宅楼比较密集。为了体现其景观的生态性，小区内有一条人工河道蜿蜒而过，把小区的空地分割成大小不一的碎片。河边花香草绿，绿柳成荫，不少凉亭假山点缀其间。但仔细观察便可发现，小区里可供居民活动健身的空地却十分有限，最大的一块空地，只能容纳30人共同活动。每次看到“芳草青青、留心脚下”的木牌时，李奶奶总免不了要叨唠一句“景有了，可人没了”。事实上，小区内也建有设备完善、宽敞明亮的室内舞蹈室、羽毛球馆及各类文体活动室。但羽毛球馆和健身房是不对社区居民免费开放的，需要居民办理会员卡。舞蹈室在有对外演出活动时用于排练使用，平时都上着锁。其他文体活动室都有一定的开放时限，利用起来并不方便。
离瑞丽花园小区不远的南平巷地区是一个具有完整元代胡同院落肌理、文化资源丰富的棋盘式传统民居区，迄今还有2万多名居民生活在此。
已经在此生活20多年的康阿姨对记者说，当初这里特别清净，没有商业化，更没有这么多的游客。可是到了2006年进行商业开发以后，南平巷变了样子，喧哗的酒吧、随意改建的建筑物、各种小吃店、水果摊占道经营。人流量和车流量骤增，传统的文化气息荡然无存。近两年，因为这里的居住环境条件每况愈下，商品价格攀升，老住户纷纷外迁，老宅成了外来人口的聚集地。
在如何把握历史文化保护、商业发展和居民人居环境三者之间的关系问题上，业内人士认为，彻底停止商业，或者迁走所有居民，都不是良策。因为，X市的“根”就在这些胡同里，在这里居民的身上。
最近，一则消息让X市居民颇为兴奋。一座包含超大的绿地，融合生态、文化、休闲等多种功能的，面积近2平方千米的文化公园将在中心城区一块被认为最具开发价值的“潜力板块”破土动工。专业人士认为，公园不只是供市民休闲娱乐的实体，同时也包含丰富的人文意义和文化价值。对一个好的城市公共场所而言，“建设”只是一个基础，其塑造和养成不只在“造景”，更要借此“化人”。随着空间的变化，人们对城市的观感会变，对城市的体验度会变，相应地，城市治理的思路要变。拿出黄金地块做公园，提供的是场所，面向的是全体市民，彰显的是城市价值。每个在这里生活、工作的市民，都能感受到这座城市带给他们的幸福感、归属感和安全感。在强调“共享”发展理念的当下，这意味着城市治理观念的一次重大转变。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (28, 5, '材料5', '17世纪的巴黎，一座桥梁扮演了今天埃菲尔铁塔的角色，这就是新桥。巴黎人，无论贫富，都很快接受了新桥。王公贵族们突破正统的束缚，在桥上纵情欢乐，贫困的巴黎人，也来这里躲避夏日的炎热，不同层次的人在这里交流接触，新桥成为社会平衡器。
新桥就好像是一个“新闻发布中心”。当时的资料显示，只要在新桥张贴消息广告，很快就能聚拢大批人阅览。巴黎人可以在这里了解巴黎发生的大事小事，各种消息都会在人群中迅速传开。此外，一些反映社会现象的歌曲也在此广泛传播，以至于产生了许多“新桥歌手”。作家赛维涅侯爵夫人认为“是新桥创作了这些歌”。而这些歌曲也只是冰山一角。在17世纪30年代专业剧场诞生之前，新桥还一直是巴黎戏剧的中心。正如一幅17世纪60年代的绘画所示，演员们在临时搭建的舞台上表演，各行各业的人聚集在周围，甚至凑到舞台底下。露天表演是造成新桥交通拥堵的一个原因，另外一个更重要的原因便是桥上的购物活动，新桥一竣工，街头市场就出现了，各种新奇的东西这里都可以找到。没有人会预料到，这座桥会成为各色人为不同目的而争夺的空间。
在十几年前的圣保罗，经常可以看到富人区被高高的院墙和铁丝网包围、门口警卫森严的景象。其原因是贫富差异过大，富人为了寻求安全导致居住空间分异。贫困区税收锐减，政府提供的警力、学校、医院等公共服务质量下降，这又促使一些中等收入的家庭迁走，公共空间迅速衰败。一些人为了生存针对富人下手，或偷或抢，富人只能选择加强保安防范措施。这样的治安环境，无人敢去投资。于是，政府借助城市设计，恢复城市公共领域的功能，让市民在交往活动中逐渐消解对立情绪，进而吸引投资，重新复元。
近30年来，西方国家把大量工业化时代遗存的码头、厂房、矿场改造成为向公众开放的公园和文化广场。在城市中心区，“商业步行街”几乎成为城市更新的“标准选项”；在城市边缘地带，提供大尺度、复合化、向公众开放的商业空间，也成为地方政府和私人开发商最乐意采用的策略之一。这些购物中心、主题公园和广告天地，被设计得优雅、别致、生机勃勃，成为日常生活审美化的最典型不过的展示空间。有研究者说，城市建设与管理的目的如果仅仅是为满足经济或某种美观诉求，显然是片面的，甚至是短视而危险的。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (28, 6, '材料6', '走进独墅湖月亮湾商务区，你会发现，这里的道路格外平整，找不到一条“马路拉链”，天际线由棱角分明的建筑物和绿树组成，空中也看不到一张“蜘蛛网”。这是因为，这里的自来水管、供电电缆、通信电缆全部“住”到了地下宽敞的“集体宿舍”里。这就是S市第一条城市地下公共空间基础设施——月亮湾地下综合管廊。城市地下综合管廊作为地下空间的“生命线”，是城市公共配套建设的重要组成部分。
月亮湾地下综合管廊，自2011年11月建成投入使用，已平稳运行多年。这是一个全长920米、断面3.4×3米的“T”形长廊。长廊的一侧是一排长长的钢铁支架，如同“超市货架”，从上到下依次放着消防与监控线路桥架、电力线路桥架、两层通信网络桥架，最下面三层空着的“货架”是为未来管线预留的空间。管廊内另一侧是上下两根直径70厘米的集中供冷管道。技术员介绍说：“附近商务区的写字楼不用中央空调，夏天由这两根管道集中供冷。”
S市管线管理所负责人在向记者介绍管廊建设的前期准备情况时说，由市长担任组长的市地下综合管廊工作领导小组起到了关键作用，领导小组成员有39人之多，涵盖了辖区各板块、各相关单位主要负责人。专门机构的设立，形成了多元主体的常态化沟通和快速推进机制，有效避免了推诿扯皮、难以协调等问题。在领导小组的组织下，相关部门编制完成了《S市地下空间专项规划（2008～2020）》《S市地下空间规划整合（2012～2020）》，今年6月又出台了《S市地下管线管理办法》，统筹加强对地下管廊规划、建设和安全运行的管理。
“地下综合管廊造价和维护可不是一般的昂贵”，管廊开发公司徐总经理给记者算了一笔账，“使用寿命为50年及100年的地下综合管廊，每公里建设运行成本分别为1.6亿元及2亿元。即使S市经济实力不错，但借力社会资本也是现实的必然选择。”市政府授权S市城市建设投资发展有限公司出资组建了S市管廊开发公司，其中城建平台占股45%，水务占股20%，4家弱电单位各占股5%，为供电预留股份15%。管廊开发公司，专门负责城市地下综合管廊的投资、建设、运营和管理事务，不仅解决了资金问题，也解决了建设主体的问题。
在记者参观的时候，工作人员介绍：S市地处江南水网区域，地下工程施工难度大，精度要求高。为确保工程的顺利推进和质量安全，S市在前期调研分析基础上，根据国家《城市综合管廊工程技术规范》，组织专家团队反复论证，最终为项目设计施工提供了充分依据。S市在综合管廊规划设计阶段，就确立了系统化、标准化、智慧化的目标，在铺设管线时同步建设全面的监控、感知系统，并为信息系统升级留有接入口，方便日后对大面积地下管线实施统一综合管理。建成的综合管廊囊括消防、照明、排水、通风、通讯、供电、监控感知、火灾报警等系统，可以通过一个终端对所有管线进行实时监控和调度管理，并具有自动检测、定位、提醒等多种功能，真正实现了信息化、一体化、智能化管理。
由于综合管廊建设成本高，入廊管线大多具有公益性，且这一新生事物在使用过程中权、责、利还缺乏有效制衡和匹配，导致社会各方的投融资积极性都不高。为此，S市借鉴国内外经验，特别规定除争取国家试点和省财政支持外，如果项目建成后特许经营期内收费不能实现预期目标，市财政将进行一定补贴，确保股东投资安全且获得基础收益。
根据工程内容、建设成本、运营周期、物价水平等多重因素，制定收费项目和收费标准，明确各单位可以以入廊或租赁的方式获得管线所有权、使用权，让管线需求者根据自身实际情况选择使用方式，调动其入廊积极性，增加管线使用效率和经济收益。
管廊收费之所以困难，很重要的一个原因是缺乏调动入廊单位积极性的有效方式。S市创新性地以打造利益共同体的方式，吸引电力、给排水、通信等单位成为管廊建设主体——管廊开发公司的股东，让各单位根据自身需求充分参与管廊的规划、设计和建设过程。在合理确定收费标准的基础上，为盘活资产、提高综合收益，这些单位均愿以有偿方式使用管线。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (28, 7, '材料7', '月亮湾地下综合管廊建设给人们以很大的启示。那里地上道路平整，天空没有一张“蜘蛛网”，城市公共空间发展的潜力倍增。这让人想到《老子》里的话：“凿户牖以为室，当其无，有室之用。故有之以为利，无之以为用。”老子以人们居住的屋子为喻，他说一间屋子，开凿门窗，修建四壁，只有形成虚空部分，它才具有一间屋子的良好功能。据此，老子提出了“有之以为利，无之以为用”的观点，强调“有”与“无”都具有不可忽视的作用。瑞丽花园小区的李奶奶，离开广袤的田野，住进了单元楼，总觉得“喘不过气来”。看来，李奶奶虽不是哲学家，但在感觉上与老子“有”“无”之用的理念暗合。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (28, 3, '三、作答要求
（一）“给定资料1”和“给定资料2”反映了改革开放以来我国农村土地承包政策的发展过程，请你概述这一发展过程。（10分）
要求：
（1）准确、全面，有条理；
（2）不超过200字。
（二）“给定资料2”中，L村村支书面对村民土地调整的要求，发出感慨：“这样一来，我们的压力很大，看来村里的土地调整也不是一个简单的事。”请根据“给定资料2”，分析他为什么感到压力很大。（10分）
要求：
（1）全面、准确，有条理；
（2）不超过200字。
（三）“给定资料4”提到，“城市建设与管理的目的如果仅仅是为满足经济或某种美观诉求，显然是片面的，甚至是短视而危险的。”请根据“给定资料3”和“给定资料4”，谈谈你对这句话的理解。（20分）
要求：
（1）观点明确，分析全面，有逻辑性；
（2）不超过300字。
（四）S市将举办“城市样板工程展示会”，请你根据“给定资料5”，就其中地下管廊建设情况撰写一份讲解稿。（20分）
要求：
（1）紧扣资料，内容全面；
（2）逻辑清晰，语言准确；
（3）不超过400字。
（五）“给定资料6”中提到了老子关于“有”和“无”的观点，请你围绕给定资料反映的城市建设理念中的问题，联系实际，以“试谈‘有’与‘无’”为题写一篇文章。（40分）
要求：
（1）自选角度，见解深刻；
（2）参考“给定材料”，但不拘泥于“给定资料”；
（3）思路清晰，语言流畅；
（4）总字数1000字左右。
2018年国家公考《申论》真题（地市级）（解析）', 10, 200, '3.土地零散、收益低；种地费时费力、积极性低。');
INSERT INTO shenlun_paper (id, paper_code, title, year, version, question_count) VALUES (29, '2019-ds', '2019年国家公考《申论》真题（地市级）', 2019, '地市级', 1);
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (29, 1, '材料1', '1.本题本由给定资料与作答要求两部分构成。考试时限为180分钟。其中，阅读给定资料参考时限为50分钟，作答参考时限为130分钟。
2.请在题本、答题卡指定位置上用黑色字迹的钢笔或签字笔填写自己的姓名和准考证号，并用2B铅笔在准考证号对应的数字上填涂。
3.请用黑色字迹的钢笔或签字笔在答题卡上指定的区域内作答，超出答题区域的作答无效！
4.待监考人员宣布考试开始后，方可开始答题。
5.所有题目一律使用现代汉语作答。未按要求作答的，不得分。
6.监考人员宣布考试结束时，应立即停止作答，将题本、答题卡和草稿纸都翻过来留在桌上，待监考人员确认数量无误、允许离开后，方可离开。
严禁折叠答题卡！
二、给定材料');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (29, 2, '材料2', '前些年，小张辞去了城里的工作，回家乡的镇上当了一名快递员。下面是他讲的“三农”新故事：
前些年，快递公司刚进这个镇时，全镇每天收发的包裹只有几十个。到村里送快递，碰到下雨天，三轮车陷入泥里，经常要下来推车，送完快递回来，鞋子上总会沾上半斤烂泥巴。那时挺后悔把城里的工作辞了，感觉很失落。
这几年大家的生活水平上去了，网购的人越来越多，我的业务也好了起来。特别是前年，镇上的快递公司联合农林服务中心、电商协会给大伙上起了包装技术培训课，现在咱这里的瓜果蔬菜都用上了真空包装、低温保鲜技术，快递公司也更乐意接这种订单。有了销路，家里种的就不愁卖了。
比如说吧，咱这里的枇杷很有名。以前，乡亲们摘回枇杷后，要乘两个多小时的公交车到几十公里外的城里火车站广场叫卖。那时，品质优良的枇杷也卖不上好价钱，有时连本钱都挣不回来。如今，镇里的枇杷大部分是通过电商平台销售的。每到枇杷采摘季，镇里的文化广场就会成为快递员的临时收揽点，乡亲们排着队邮寄，场面好不热闹。
现在咱镇里的电商差不多有500多户了。去年镇里投资建了个农产品电子商务产业园，把大家拧在一块闯市场，今年镇上的生意就更好了。加上上个月新开的那家快递公司，我们镇里已经有了4家快递公司。
如今大家腰包里有了钱，心气足了。我同事杨大哥这几年靠送快递，摘了帽，主动要求退出了低保。大伙对生活也讲究了起来，希望村子能漂亮些、路能好走些，闲时有地儿跳跳舞、下下棋。这不，政府投了很多钱搞建设，镇里几个大的村子，都通上了柏油路，路边插上了太阳能路灯，现在我们送快递方便多了。镇边上，搞旅游的那个村子，街两旁不仅修了排水沟、统一摆上了垃圾箱，还把老百姓的房子都整了整，青瓦白墙的，远远看，像画里似的。
最近从城里回来的人，越来越多。要么像咱一样，做做快递，或者在镇里的企业打打工；要么回家接班，种点养点啥，通过快递卖出去，不比打工挣得少，还图个自在。原来乡下的钱往城里跑，现在城里的钱开始喜欢往村子里跑。城里人来我们这投资的越来越多，要么开工厂、搞农产品加工，要么办民宿、搞乡村旅游。
和刚回来那会儿比，我现在心里踏实多了。上个月和爱人商量，打算承包村西头一块撂荒的地，再把周边几家的田一起租过来，像村里老李他们一样，也办个家庭农场。我想只要好好干，生活会越来越好的！');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (29, 3, '材料3', '小赵是省派驻村干部，2015年远赴大山深处的池口村担任村党支部第一书记。下面是他讲的“脱贫攻坚”故事：
我从省城出发，颠簸了10多个小时，才到了池口村。跳下车，映入眼帘的是光秃秃的石甸山。村支书老韩招呼我在村口吃了一碗石甸花椒酱面。虽然花椒麻得嘴好久没有感觉，但是花椒酱独特的鲜香口感让我赞不绝口。老韩在旁边笑着说：“石甸花椒酱可是咱这里的宝贝。”吃完饭，放下行李，老韩陪着我到村里走了走。刚开始我还挺乐观的，看上去这村子不穷啊，但是越往村里走，我的心就越凉。村民老左家的房子没有门，房间里没有家具、家电，屋子的一角堆着一堆杂粮，炕上的被子已经看不出颜色。老左告诉我：池口村地薄、种粮食收成低，只够糊口。除了种地，自己也不知道还能干些啥。现在家里穷，一天只能吃两顿饭。像他这样的人家，村里还有好几户。
回村部的路上，老韩指着周边的大山说：“我们是守着金娃娃挨穷呀！你看，石甸山上1000多亩地，已经荒了十几年了，如果能把这地开发好，起码吃饭就不用愁了。”接下来一个多月，我挨家挨户到农户家走访，一直在想，贫困地区缺什么？种植、养殖技术老百姓都会，但是“应该做什么、怎么做、怎么能卖出去”，这些问题不解决，村子就难以摆脱贫困。问题找到了，怎么破题呢？我想到了石甸花椒酱。这十里八村的家家户户都喜欢用花椒制作花椒酱，一日三餐都离不开它。既然本地这么多人吃，是不是能产业化，做成一个产品呢？同时，制作花椒酱对花椒的需求量特别大，也能带动花椒种植。2015年当年，我几乎走遍了省内的大型超市、批发市场，发现和目前市场上的花椒酱不同，我们石甸花椒酱麻辣鲜香、口感独特，不仅在本地有市场，还有可能借助电商扶贫政策卖到全国去。
有了想法，还要有办法。听说要开发石甸花椒酱，不仅是村民，许多村干部也都不相信。老韩说：“万一卖不出去怎么办？咱们可赔不起啊！”为此，我带着村干部不但到周边县区了解情况，还专程到省食品研究院咨询石甸花椒酱产业化的可行性，请教生产加工、质量检验以及食品安全等问题，排除了花椒酱存在有害成分和菌群超标的可能性。这次调研，统一了大家的思想。老韩说：“小赵书记，咱们村干部都认定你了，今后我们跟着你好好干！”2016年10月，当地第一家村集体企业池口农副产品开发有限责任公司挂牌，村民可以技术入股或半成品入股。我代表公司与省食品研究院、省中小企业公共服务平台签订合作协议，共同开发、推广石甸花椒酱。2017年初，第一批石甸花椒酱上市后，短短几天就销售一空，村民们都乐坏了。仅靠石甸花椒酱一项，去年村集体就实现了66万元的收入。
我始终没有忘记老韩说的石甸山，没事就上去转悠，考虑到底该怎么开发。2015年外出做市场调研时，我看到梅花椒价格非常高，就帮着村里申请到“惠农贷款”，买了1000棵树苗，种到山上。现在，石甸山已经种植梅花椒500多亩，成为池口村的“绿色银行”。现如今，我不管到谁家，都留我吃饭，谁家杀鸡或者杀羊，都会想着我。老韩风趣地说：“小赵书记，你现在是我们这的‘狗不叫干部’，乡亲们的狗见了你不但不叫，还直摇尾巴哩。”');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (29, 4, '材料4', '小吴是北方某地宁堡村大学生村官。下面是她讲的“成长”故事：2016年，我被组织选派到宁堡村担任村主任助理。那时我觉得自己是大学生，肯定比农民强。村干部和村民们对我都很客气，但就是不分配活儿给我。那时我最大的活儿就是“看家”，大家出去办事，让我守在村部。我也不愿闲着，为了证明自己，一开会我就抢着发言，但不管我说得多么激情澎湃，大家一点反应也没有。第一次下田干活，我就把鞋陷进了泥里，旁边有人说：“这大学生下地还得跟个提鞋的。”
刚到村里，我看很多事不顺眼，总觉得自己在理，大家做事应该按照我的想法来。村里核发水田地补偿款，要量土地，村支书认为我是外村人，能一碗水端平，就让我负责这事。有几个人找我说情，想要皮尺松一点，好多得点补偿。我一点不让，把尺绳拽得紧紧的。结果一位村民当场质问我：“你个外来人，想干啥？”
第一年年终评议会上，有4个人给我投了不合格票。我的委屈突然爆发，回到屋里就哭了，觉得自己表现挺优秀，关键是我也一直想要给村里干事，怎么还受这气？当时，村支书跟我讲了一番话，对我触动很大：“你坚持原则是对的，关键在怎么做。有理还不够，在村里得想办法跟老百姓把理说通。要把理说通，首先你得和大家干在一起。”他建议我，每天到老乡家干农活，一次两个小时。
从那以后，我开始努力学说土方言，走水田地、学农活。每天“服役”两个小时，每次换一家。手掌上的血泡起了破，破了又起，汗水渍透了衣服。我慢慢感受到了农民的不易，也理解了“脚下沾有多少泥土，心中就沉淀多少激情”的含义。一段时间下来，和大家熟络了，村民们从自家娃娃读啥学校、看病到哪个医院、添置家电买啥牌子，到调解邻里矛盾都愿意找我帮忙。村里一户人家因为不满征地补偿，不断上访。那段时间，我不时到他们家串门、唠家常，见他们家生活困难，就帮着申办救济，这户人家深受感动，后来再也没有去闹了。我还发挥自己的专业优势，成功创建本村优质杂粮品牌并打入南方市场，为大家闯出了一条增收致富的新路。去年，我被市里评为优秀大学生村官。
现在，村里人对我的称呼，也渐渐从“那个大学生”变成了“小吴”。“小吴来了啊！”“小吴吃了吗？”上了年纪的，则直接叫我“小吴闺女”。我之前不太把这些话放在心上，体会到这些关心来之不易后，每次听到心里都暖暖的。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (29, 5, '材料5', '为讲好新时代“中国故事”，某地市委宣传部组织文艺工作者到基层采风，体验生活。在活动结束的座谈会上，大家交流了参加此次采风活动的心得体会。以下是部分与会人员的发言记录：
甲：我创作历史剧的目的是，用艺术的手法对历史进行重新包装，通过故事唤起人们认识历史的兴趣。可是，有些作品为迎合当下的“娱乐精神”，将现代元素掺杂进历史，剥离具体的历史语境肆意发挥。虽然，让观众看着新鲜稀奇、招人眼目，收到了娱乐效果，但是，这种混淆现实与历史的做法，牵强附会、哗众取宠，是对历史的不尊重。
我正在创作一部反映改革开放40周年的作品。如何真实反映时代，塑造时代典型，通过人物命运变迁折射出整个时代的图景，是我常思考的问题。所有的人都是时代里的人，都有他的时代性，而追究时代性，就不能没有历史感，正是因为历史才造就了时代。岁月能滋养人的心性与才华。我们这一代人出生在改革开放开始的时候，到了这个年龄，有了一定的能力，有责任创作出富有新时代气息的作品来。
乙：我是乡村出来的80后。我的文字大多从儿童、女性视角入手，展现基层百姓的生活状态、普通人家的人生故事。我自己曾以一个乡村媳妇的身份在认真地生活，和乡村里那些小媳妇一样流汗流泪、上山下田、柴米油盐、家长里短。后来我进了城，但幼小多病的儿子只能暂时寄养在婆婆家里，成为“留守儿童”。从那时起，我就开始注意“留守儿童”，每当看到他们胆怯而忧郁的目光，我心里就有一种疼痛在撕扯。从此，我有空就往附近村庄跑，了解情况，搜寻故事，捕捉细节。我的写作就是从那时开始的。
我认为，创作不仅要表达自己，还要善于书写他人。如果我们的创作只停留在私人性的经验上，仅仅满足于自我倾述的需要，那么作品就难以回应时代的提问，体现老百姓的真情实感。
丙：我写网络小说快十年了，在网上发表了不少作品。我们这一代人，在互联网的影响中建立和重构自己的精神世界。创作时我总是喜欢把自己投射到一个具体的情景中，在一个自我编织的虚幻氛围里，想象故事的情节然后记录下来，写成文字。有时需要写一些自己不熟悉的背景情节，只要坐在家里，上网搜索素材，我就能继续写。
这几年，我在网上写连载赚到了钱，但是没有写出自己满意的作品，感到现在的创作动力也没有之前那么强烈了。认真想来，手机、网络这些现代技术方便了创作，加上经济刺激，造就了我的“高产”。但是技术和金钱，在更深的层面上给创作造成了某种“遮蔽”，让我感受不到阳光的温度，忘记了创作的初心。
丁：我的新作是脱贫致富的故事。上个月，我走进大山深处的一处村落，才感到生活的落差太大了。城市经济发达、生活便利，很难想象为了供一个孩子上学，偏远地区的贫穷家庭要经历什么样的苦难。我感到，只有继续深入下去，进一步了解农村的生存状况和精神世界，对政策在基层执行有更多角度的观察，才能明白国家精准扶贫是多么伟大而艰巨的任务。现在我要把以前想象的人物情节全部推翻，重新创作。
这次采风让我感到，多走多看多聊实在太有用处了。“行走”要成为我们文艺工作者的生活常态，既要行走在书本中，更要行走在现实生活里，依靠“行走”才有可能打破乡间田野和城市高楼之间的隔阂。
……
主持人：我们组织这次采风活动，就是希望大家能够更多地深入基层，到老百姓中间去走一走，创作出更多的优秀作品来反映我们所处的这个新时代。今天大家的发言都很精彩，也谈到了当前文艺创作中存在的这样或那样的问题。特别是，丙使用的“遮蔽”这个词很形象。如果不能打破这种种“遮蔽”，就拿不出有份量的作品。创作的力量只可能来自于我们脚下的大地和身边的人民。我们只有将个人情感与国家命运紧密相连，才能创作出那些有时代精神、有思想深度、有生活温度的故事。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (29, 6, '材料6', '自古以来，我们的祖先就关注现实，关注生命，关注生命层次的提升，将“为国利民”作为至善的人生追求。
中国核潜艇第一任总设计师彭士禄，在他3岁时，母亲蔡素屏不幸被捕就义，第二年，父亲彭湃在上海被捕，慷慨赴死。年仅4岁的彭士禄成为孤儿，过起了姓百家姓、吃百家饭、穿百家衣的逃亡生活。1962年，这位历尽苦难长大的孩子，开始主持我国潜艇核动力装置的论证和主要设备的前期开发。当时，他手里仅有的参考资料是，从报纸上翻拍的两张模糊不清的外国核潜艇照片和一个儿童核潜艇模型玩具。1967年起，他在大西南深山组织建造潜艇核动力陆上模式堆。那些日子里，他吃住在阴暗潮湿、毒蛇蚊虫肆虐的工地上，靠着原始的计算尺和手摇计算器验证了核潜艇数不清的数据。1974年8月，我国自行研制的第一艘核潜艇正式服役。从投身核潜艇研制到项目解密，隐姓埋名近30年，彭士禄始终忘不了周总理嘱咐他的话：小彭，记住，无论什么时候，无论走到哪里，你都要记住你姓彭，是彭湃的儿子！
苏和被誉为“沙漠愚公”。2004年，曾任阿拉善盟政协主席的苏和，回到老家额济纳旗，在大漠中的黑城遗址旁植树造林，那一年他57岁。黑城遗址是一座有着近千年历史的西夏古城，沙化严重。苏和回忆说，小时候听长辈们讲，这附近林草茂密，胡杨、红柳密得骆驼进去都找不见，可上世纪五六十年代后，生态日趋恶化，大片植被枯死，风沙天气越来越多，额济纳旗甚至成了沙尘暴的策源地。他说：“周围风刮过来的沙子堆得和城墙一样高，眼看黑城快要被埋掉了。我当时有个想法，黑城不能在我们这辈人手上消失。”10年间，他种植的梭木林一点点扩大，达到了3000亩。最初在房后种植的两棵胡杨也长成了大树，老人被太阳和风沙磨砺过的坚毅的脸上刻满皱纹，满是伤痕的大手上，老茧褪了一层又一层。
从河南南阳市镇平县城出发，一路向北，经高丘镇，沿山路盘旋而上，攀至海拔1600多米的山顶，再顺山路蜿蜒而下，下到海拔600多米的谷底，才能到达张玉滚任教的黑虎庙小学。这所学校被层层大山包围，村里流传着一句顺口溜：上八里、下八里；羊肠道、悬崖多；还有一个尖顶山。从学校走到镇上，需要10多个小时。然而，就是在这样的环境下，当年21岁的小伙张玉滚来到这里当小学教师，一直坚持到现在。张玉滚之所以选择留下来，是因为前任校长吴龙奇的一句话：“玉滚，泥巴砖头垒个灶台，顶多能用个十年八载。咱们教学生认的每个字，他能用一辈子。你要不来，这个班就开不了课，孩子们就得上山放羊去。”17年间，张玉滚教过500多名孩子，村里出的大学生从1名增加到了16名。
阎肃是我国著名的艺术家，作品影响了几代人。他曾经感慨说：“我没有决定过自己一生的道路，或者说去想我这一生必须要怎么样。跟着时代的大潮往前走，尽到我所有的力量，做好我要做的事情。不要去挑生活，让生活来挑你。时代也好、组织也好、环境也好，需要你做什么事，努力把它做好，对你自己就是一件非常快乐的事情，别人也会觉得快乐。我的一生作品不少，只要能在老百姓的心里留下一点记号，那我此生无憾。我对我的子女也是这样的要求，不去安排自己的人生道路，听时代的招呼，做一个对社会有用的人，对得起这个时代就够了。”');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (29, 3, '三、作答要求
根据“给定资料1”，请概括小张家乡出现的新变化。（15分）
要求：准确全面，条理清晰。不超过200字。
省里召开扶贫工作座谈会，邀请小赵介绍发展花椒酱产业的经验。根据“给定资料2”，请为小赵写一份发言提纲。（20分）
要求：（1）紧扣资料，内容具体；（2）语言简明，有逻辑性；（3）不超过400字。
根据“给定资料3”，请分析小吴发生了哪些变化，使得村民们对她的称呼从“那个大学生”变成了“小吴”。（10分）
要求：准确全面，恰当提炼，条理清晰。不超过200字。
“给定资料4”中的座谈会上，主持人说：“如果不能打破这种种‘遮蔽’，就拿不出有份量的作品。”请谈谈你对“种种‘遮蔽’”的理解。（15分）
要求：观点明确，紧扣资料，准确全面。不超过200字。
（五）“给定资料5”提到“跟着时代的大潮往前走，尽到我所有的力量，做好我要做的事情”，请深入思考这句话，自选角度，联系实际，自拟题目，写一篇文章。（40分）
要求：
（1）观点明确，见解深刻；（2）参考“给定资料”，但不拘泥于“给定资料”；
（3）思路清晰，语言流畅；（4）字数1000～1200字。
2019年国家公考《申论》真题（地市级）（解析）', 15, 200, '3.被技术遮蔽，沉迷虚拟世界，无视现实生活、社会实践。');
INSERT INTO shenlun_paper (id, paper_code, title, year, version, question_count) VALUES (30, '2019-sb', '2019年国家公考《申论》真题（副省级）', 2019, '省部级', 1);
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (30, 1, '材料1', '1.本题本由给定资料与作答要求两部分构成。考试时限为180分钟。其中，阅读给定资料参考时限为50分钟，作答参考时限为130分钟。
2.请在题本、答题卡指定位置上用黑色字迹的钢笔或签字笔填写自己的姓名和准考证号，并用2B铅笔在准考证号对应的数字上填涂。
3.请用黑色字迹的钢笔或签字笔在答题卡上指定的区域内作答，超出答题区域的作答无效！
4.待监考人员宣布考试开始后，方可开始答题。
5.所有题目一律使用现代汉语作答。未按要求作答的，不得分。
6.监考人员宣布考试结束时，应立即停止作答，将题本、答题卡和草稿纸都翻过来留在桌上，待监考人员确认数量无误、允许离开后，方可离开。
严禁折叠答题卡！
二、给定材料');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (30, 2, '材料2', 'S市积极响应十九大报告中“要坚持农业农村优先发展，按照产业兴旺、生态宜居、乡风文明、治理有效、生活富裕的总要求”，坚持将乡风文明建设放在全市发展大局中进行谋划，大力推动农村综合改革、美丽文明村居建设、基层大治理等工作，把乡风文明建设作为重要内容加以部署。为加强基层治理，推动乡村振兴，今年3月13日，S市召开工作大会，对村居建设作了整体部署：到今年年底完成30个美丽文明和谐示范村建设，到2020年年底完成50个示范村居、5个标杆村居建设，按照典型引领、整体推进、总体提升的方针，将乡风文明建设进一步推向深入。
S市一直重视基层党建工作，大力实施固本强基工程，突出村级党组织领导核心作用，按照“党领导一切”原则出台了一系列政策，努力健全以党建为统领、以法治为核心的基层治理体系，通过党组织的有力领导，促进矛盾纠纷的化解和法治观点的强化，逐步提高乡风文明水平。
今年S市选派了104名机关干部任村居第一书记，公开招考205名优秀大学生担任村干部，并推进基层党建下沉到村民小组，落实支部建在小组上。该市党建工作示范村A村牢记习近平总书记“农村党建要让群众更满意”的殷切期望，积极探索“党建+”融合基层治理发展模式，以党建引领基层自治、共治、法治、德治。
S市注重提升城市形态，大力推动城市升级，“美城行动”从中心城区延伸到村居社区。在乡风文明建设过程中，S市以改造乡村人居环境为核心，深入推进农村环境综合治理和生态文明建设，全面提升农村整体环境，取得了明显成效，绿化、美化水平显著提升。
S市共投入2000多万用于文化遗存的修缮和活化。全市现有国家级、省级、市级非物质文化遗产共28项，国家级、省级、市级非遗传承人共27人。S市坚持“一村居一品牌”的工作思路，挖掘提炼村居历史文化特色，打造村居文化品牌活动。
目前全市已建成30个村居主题公园，143个农村公民道德讲堂，每个村居都设置了善行义举榜或好人榜，让核心价值观随处可见、随时可学、随心可感。
S市不断加强核心价值观宣传教育，推进主题公园、标识景观、公益广告建设，开展农村道德模范和身边好人学习宣讲活动，引导村民树立正确价值观念。同时，S市还大力加强农村思想道德建设，深入挖掘农村传统道德教育资源，引导村民在思想观念、道德规范、知识水平、素质修养、行为操守等方面继承和弘扬优良传统，形成积极、健康、向上的社会风气和精神风貌。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (30, 3, '材料3', '有着良好区位优势和自然条件的Y县城关镇山岔村，多年来却受人多地少、农业基础薄弱、产业结构单一等因素制约，2012年全村人均纯收入仅为3800元，约三成的人口处在贫困线下。在各方努力下，该村2013年实现了整村脱贫，2015年建成省级美丽乡村，2016年被评为市级卫生村，2017年列入小康村建设项目。日前，调研组对山岔村进行了调研，以下是调研记录：
村党支部书记L介绍说，为了彻底改变贫困面貌，2013年，村上联系帮扶单位省环保厅、相关银行，反映发展意见，争取帮扶资金。山岔村通过整合帮扶资金，建成了180平方米的文化宣传基地，安装太阳能路灯10盏，硬化村内道路3公里，硬化西环路至山岔村道路3.5公里，还积极争取财政、建设、文化、扶贫等部门资金，实施了清溪小学及幼儿园新建工程。
该村还积极鼓励农户成立合作社，通过土地流转，形成合作社式的劳作模式，发展现代设施农业、养殖业，并引导群众有计划地种植经济作物。
杨自龙家以前是村里有名的贫困户。原本东奔西走做临时工的他，在村党支部的鼓励下，争取到帮扶贷款90万元以及村级发展互助资金协会所注入的资金30万元，牵头成立了吉隆田农产品产销专业合作社，先后搭建起17座大棚种植草莓。因为绿色环保，来采摘的人很多，经济收入年年增长。
据记载，山岔村以前有九盘水磨，它们在清朝同治年间被焚烧殆尽。清光绪初年，本村村民王生贵、王好存父子重新修建一盘水磨，用于解决老百姓无处磨面的问题，加工场面十分红火。这盘具有传奇色彩的水磨保留到了今天，它不但让后人了解先辈生活，也激励了大家齐心奔小康的勇气，被Y县人民政府授为县文物保护单位。
“我们确立了‘一心多景、一轴三廊、四片联动’发展格局。”城关镇党委书记X如是说。他介绍，山岔村2014年被纳入了市级美丽乡村建设行列，城关镇抓住这一机遇，积极为该村出良策，确定以“传承九磨文化、做足山水文章”为主线，因地制宜发展乡村旅游业。该村下决心把发展乡村旅游作为带动全村致富的一个新举措，依托自然资源，发挥山岔村天然水源的优势，彰显历史印记，融合文化元素，做活水的文章，打造避暑休闲的美丽村庄。
L书记说，该村2014年修建了占地650平方米的老年文化活动广场，2015年利用省市县三级配套资金打造了占地7800平方米的水磨文化广场，2016年建成了2000平方米的人造草坪球场并精心打造了400米长的历史文化艺术墙。这些设施不仅丰富了群众文化生活，而且使村民在潜移默化中受到教育，社会风气也越来越好。
山岔村古时就因县八景之一的“烽火夕照”而负盛名。夕阳将落未落之时，晚霞赤红如血，涂遍半边天空，如一幅色彩溢漾的油画。置身此处，山川河流尽收眼底，其景象在夏日最为艳丽壮观。据此，山岔村2016年建成烽火夕照长城墙、山神庙观景平台和小游园，同时恢复了重阳民俗文化活动。
“我们村已通过省、市美丽乡村建设验收，打造了一个不要门票的乡村旅游景点。到这里来，能品野菜、听蛙声、忆水磨、体验农耕文化，看得见山，望得见水，留得住乡愁。”L书记高兴地告诉我们。
依托美丽乡村建设，部分村民办起了农家乐。周云是村里的致富带头人，2014年市级美丽乡村建设时，他看到了商机，有效利用自家宅院，开办“农家乐”。“道路全部硬化，环境干净整洁，景观美丽还有故事，这吸引来了不少游客，生意一天比一天好，1个月纯利润有1万多元。”周云笑呵呵地说。
L书记介绍说：“周云的农家乐开办为山岔村的乡村旅游业发展开了个好头，好多村民纷纷效仿，家庭收入开始增长，生活条件明显好转了。可是新的问题出现了，男人们一闲下来就喝酒，女人们一闲下来就传闲话。镇、村都意识到了这个问题。习近平总书记说，‘实施乡村振兴战略要物质文明和精神文明一起抓，特别要注重提升农民精神风貌。’我们全面落实习近平总书记的有关指示，大力倡导文明树新风。”他指着一些农家大门边墙说：“精神文明建设的第一步就是从每一家找家训、立家规，然后制作成漂亮的牌子挂在门口，时时提醒着进出的每一个人。”他强调，家和万事兴，家庭和睦、邻里亲近，做任何事都容易。
山岔村把家训作为优秀传统文化传承发扬，在全村范围内从家谱村史、牌匾楹联、经典家训中广泛征集好家训，使该村成为户户挂家训、家家立家规的“家训村”，以文明家风推动良好社会风气形成。周云家的大门口贴的是“家庭和谐、邻里相亲”，对于周云来说，好的家训是他家庭和睦、创业致富的根本。周云说：“自从挂上了家训牌，全村的人就开始讨论张家或者李家的家风，不但监督别人，而且反观自己、要求自己、教育孩子。大家和睦相处，邻里亲近。”');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (30, 4, '材料4', '某学者发表文章，介绍了中国现代史上著名实业家卢作孚在乡村建设方面做出的历史贡献。该文章摘录如下：
卢作孚于1893年出生在原四川省合川县一个世代农耕的家庭。作为一个没有念过大学的农家子弟，他却创造了中国现代经济史、社会史、文化史、教育史上的奇迹。卢作孚创办的民生公司是中国近现代最大最有影响的民营企业集团之一。
1927年，卢作孚开始在中国西部开展以北碚为中心的嘉陵江三峡乡村建设实验，被誉为“北碚之父”，和晏阳初、梁漱溟并称中国现代史上“乡村建设三杰”。他的核心思想是：中国的现代化，基础在“乡村现代化”。他认为：“乡村是不断供给城市人口的地方。如因教育缺乏，供给的都是无知识的人口，那不惟于城市文明没有帮助，反而妨碍不小。乡村教育不发达，不但是乡村问题，而且变成城市问题了。”而“乡村经济事业如没有（和城市）同样的速度进展，亦必引起城市原料的恐慌”，大量农村人口涌向城市，“城市人口无休止地逐渐增多，更会成了城市问题。”——这些近百年前说的话，仿佛针对的就是当下的现实。他始终抓住城市与乡村发展的关系，来思考中国的发展问题，从而突出乡村建设的基础意义，抓住了要害。
“乡村现代化”，既是一个奋斗目标，更规定了推动乡村运动的范围与方法。这也是最具启发性之处：从事乡村运动，既要落实为一个个具体问题（教育问题、救济问题等）的解决，但又不能局限于此，要有一个“乡村现代化”的大视野、大目标，既立足局部，又着眼全局。
卢作孚在设计嘉陵江三峡乡村建设时，一开始就提出了“要将嘉陵江三峡布置成为一个生产的区域、文化的区域、游览的区域”的目标，并且具体规划为经济建设、文化教育建设、社会建设、环境建设、自治建设等几个方面。这表明，卢作孚的“乡村现代化”是一个“全面现代化”的概念，并不局限为物质的建设，而追求乡村政治、经济、文教、社会、环境的全方位的改革。其一，卢作孚规划中的文化教育建设，不仅以“教育事业”为中心，而且把“研究事业”放在突出的位置。在他看来，乡村建设必须建立在科学研究的基础上，他因此强调服务于乡村建设的研究，“要注意应用的方面，有生物的研究，有理化的研究，有农林的研究，有医药的研究，有社会科学的研究”。后来北碚建立了西部科学院，就具体体现了他的这一思想。在城镇设立研究机构，当时这在全国是一个独创。其二，卢作孚特别重视社会建设。他不仅积极发展公共文化娱乐建设，创办博物馆、图书馆、运动场，而且大力推动“公共事业”，开展“社会工作的运动”，这背后又是“人”的建设。他要通过这些公共事业，培育新的“人民”：“皆有职业，皆受教育，皆能为公众服务，皆无（不良）嗜好，皆无不良习惯”。其三，他对环境建设也倾注极大热情，提出“凡有市场必有公园，凡有山水雄胜的地方必有公园”，他的理想是把北碚乡村建设实验区建设成“皆清洁，皆美丽，皆有秩序，皆可居住”的人间净土、乐园。其四，他在推动乡村社会建设时，特别关注的是，所有的公共事业，都要“大众出钱，大众出力，而且是大众支持。由这些具体的活动引起大众管理公共事务的兴趣，以形成大众管理公共事务的方式”。
如何着手乡村现代化？卢作孚的回答是：“政治、经济、文化这三方面的建设诚当并重，但更当以经济建设为中心，更当集中一切力量于经济建设。”只有经济建设的发展，才能“增进人们的富力”，人民富裕了，才能增进其“完纳赋税的负担力”，从而增强国力。而卢作孚更要强调的，是“经济活动为国家最大多数人所必须参加的活动”，经济建设是最能动员最广泛的民众参与的。
他自己也身体力行，以民生实业公司总经理和北碚峡防局局长的双重身份，动员民生实业公司的财力、物力和人才、技术优势，全力支持北碚峡区的乡村建设，着手五大工程建设，即投资煤业，开创峡区煤矿业；投资交通业，修筑铁路；投资纺织业，建立大明染织厂；投资科学研发，创建科学院、博物馆；投资教育，创办兼善实业股份有限公司，以企业养学校。而民生公司自身也从中获得了发展新机遇：不仅获得经济利益，而且利用乡村建设所提供的良好的社会、学习环境，培训了近千名的建设骨干人才。卢作孚力图构建一个“以工辅农，工（工商业）农（乡村建设）互动”的发展模式，其意义和影响是深远的。这一点在强调以工哺农，建设新农村的今天，就看得更加清楚了。
卢作孚乡村建设思想最核心的一个层面，即他所提出的“训练人是一切问题的中心问题”的命题与任务。他提出以“人人都能自立，人人都能立人”为乡村建设的根本目标。这应该包含两层意思：一是乡村现代化建设最终要落实到“立人”，即我们今天所说的“人的现代化”。二是乡村现代化建设又要依靠“人人都能自立”的建设者去推动。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (30, 5, '材料5', '关于如何重新认识乡村生活的意义，有学者撰文指出：
美国作家梭罗曾经倡导一种简朴的物质生活和丰富的精神生活，他28岁时只身一人来到家乡城外的瓦尔登湖，自建小木屋，自耕自食两年有余，“过一种经过省察的生活，去面对人生最本质的问题”。可以说，梭罗在乡村生活中重新发现了我们在城市的现代文明中过分重视物质资源而失去的东西，进而启发我们思考“作为精神资源的乡村文化”对人类所具有的重要意义。
人在乡村中，最能感受到大自然的熏陶。“人在自然中”，真正地“脚踏大地，仰望星空”，这本身就是一个最基本、最重要、最理想的生存状态，同时也是最基本、最重要、最理想的教育状态。别的不说，单是在乡居生活中能够每天“按时看日出”（这是作家福楼拜提出的一个著名的生命命题），就足以使我们感悟生命的意义，尽享生命的欢乐了。梭罗曾因看早晨的阳光，而产生“黎明的感觉”，即每天都以新的眼光，以一种新鲜感去重新观察、重新发现已经司空见惯的生活，从而获得新生。作家M说，在大自然中，“体验阳光，体验美，体验幸福，体验纯净，体验温馨，体验柔情，体验思念和怀想，这样的精神生活，这样的心理空间，实在太有魅力”。正是在大自然中，我们成为一个“精神明亮的人”，这才是一个健康的人。
“仁厚黑暗的地母呵，愿在你怀里永安她的魂灵！”鲁迅在《阿长与<山海经>》的结尾书写的“地母”，很容易让人联想到希腊神话里的英雄安泰，他在失败之时总是投向大地，从母亲那里获得力量。鲁迅对故乡民间世界的依恋也颇类似于此。民间文化伴随着童年记忆构成他回忆中极具温情的人生体验，他对民间风俗的津津乐道，对民间人物不无温情的回顾都表现出民间文化对他的吸引力。鲁迅正是在他家乡的民俗、民间文化的熏陶下被培育出来的。
在中国，有一位当代作家H，他也在农村建屋，自由游走、生活在城市与乡村之间。H认为，人们对乡村的“投奔”，实质上是在投奔乡村所呈现的“文明意义”，这种“文明意义”有三：其一是自然造化的“没有一片叶子是完全相同”的“个异性”，而这样的个异性在严格雷同的“技术高精度”和大量重复的“规模经济”中已经被完全屏除。其二是“永恒”的感觉，“除了不老的青山、不废的江河、不灭的太阳，还有什么东西更能构建与不朽精神相对应的物质形式”。其三是“共有共享”的理想，“大自然无比高远和辽阔的主体，至少到目前为止还无法被任何人专享与收藏，只可能处于人类共有和共享的状态”。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (30, 6, '材料6', '“城市和农村要互补发展，”某官员日前指出，“有些经济学家总是简单地认为，只要把农村的人口搬到城市里来，就完成了城镇化，生产效率会自动提高、社会分工会自动推进，这其实是有问题的。”该官员特别强调了一个误区，即将城乡一体化变为城乡“一样化”。当前，村庄大量被拆，数量急剧减少，部分基层干部梦想一步就把农村变成城市。其所造成的后果不是城乡互补发展，而是城乡“一样化”，这不仅可能导致宝贵的乡土旅游资源的丧失，也不利于现代化农业的建设。
据此，该官员认为，未来的城镇化发展应该坚持“两条腿”并行，城市、农村协调统一，宜城则城、宜乡则乡，统筹区域发展、体现地方特色、做好产业支撑、保证公共服务、保护生态环境，让农村和城市同样美丽。
有专家指出，我们在城乡关系认识上存在一些误区。他认为，不是城市文明高于农村文明，也不是农村文明高于城市文明，两者是相互依存、功能互补的关系，所以既不能把城市文明凌驾于乡村文明之上，也不能把乡村文明凌驾于城市文明之上。
城市文明和乡村文明，人造文明和自然文明，都是应该而且可以互补的；理想的生活状态可能还是在城、乡之间自由游走。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (30, 3, '三、作答要求
根据“指定资料1”，概括S市在乡风文明建设方面的举措。（10分）
要求：全面、准确，不超过150字。
假如你是被派到Y县的调研组的一员，请根据“给定资料2”中的调研记录，就山岔村值得肯定的做法写一份调研报告提纲。（20分）
要求：
（1）紧扣资料，要点完整；
（2）内容具体，条理清晰；
（3）不超过500字。
某省政府举办了一个农村发展战略研习班，其中一项研习内容是“卢作孚的乡村建设构想”。假如你是工作人员，请根据“给定资料3”，围绕卢作孚的乡村建设理念及其现实意义，写一份导学材料，以指导学员更好地学习。（20分）
要求：
（1）内容全面、准确；
（2）层次清楚，分条作答；
（3）不超过600字。
根据“给定资料4”，谈谈你对“作为精神资源的乡村文化”的理解。（10分）
要求：准确、全面、有条理。不超过250字。
“给定资料5”结尾写道：“城市文明和乡村文明，人造文明和自然文明，都是应该而且可以互补的；理想的生活状态可能还是在城、乡之间自由游走。”请结合你对这句话的思考，自选角度，联系实际，自拟题目，写一篇文章。（40分）
要求：
（1）观点明确，见解深刻；
（2）参考“给定资料”，但不拘泥于“给定资料”；
（3）思路清晰，语言流畅；
（4）字数1000～1200字。
2019年国家公考《申论》真题（副省级）（解析）', 10, 150, '3.着力发展农村，推动乡村现代化，实现城市和乡村同步发展、城乡互通，让人在城、乡之间自由游走。
【参考范文】
文明——在乡村与城市之间
有人认为农村的发展就是把农村人赶进城市，或者把农村变成城市，这种想法是非常片面的。农村有自己独立的、城市不可取代的价值和功能。城市和乡村，人类文明和自然文明，不是谁压过谁，理想的生活还是在城、乡之间游走。
我们必须站在全局高度，打破单线思维，促进乡村综合发展，统筹城乡发展，让城乡各种保持自己特色优势，形成城乡相互独立相互依存、相互促进的互利共赢的发展局面。
要总体规划，全面布局，打破单一思维，充分利用资源，促进农村综合发展。在经济上要转变农村只能发展农业的传统观念，推动农业加工工业、文化生态旅游、餐饮休闲等服务行业发展，促进农村产业多元化。农村有广袤的土地、优美的自然环境、深厚的历史民俗文化，这些资源为乡村发展的多样性提供了基础。农村发展首先要立足农业，通过生产组织形式、加大资金技术等投入，推动农业的现代化。同时我们也要看到，农村的现代化不能简单等同于农业的现代化，我们要促进农村产业的多元化，利用丰富的自然和文化资源，发展旅游业，让农村有条件发展旅游、民俗文化节、农家乐等第三产业。此外在以经济建设为中心基础上，要促进农村生态、文化、教育、社会治理方面的发展。
乡村要发展不能片面靠乡村自身，必须要理顺城乡关系，统筹城乡发展，有机把城市的优势和农村的特点相结合，使城乡相互补充、促进。
统筹城乡发展就要把农村的丰富的自然、土地、文化资源和城市的资金、人才、技术和组织优势相结合。农村资源要开发，产业要多元化，离不开城市的支持，只有统筹城乡发展农村和城市才能共同发展。农村的土地、自然文化等资源，还需要依托城市能提供的资本、技术才能得到有效的开发。农村的旅游、休闲餐饮等服务业，也必须依托城市的消费市场。当前城市消费正在升级，人们已从吃得饱、吃得好向吃得绿色、健康转变，对绿色、优质中高端农产品的需求被激活，这是农村的历史发展机遇。
城市对农村的输入不是单向的，乡村绝不是单方面地接受工业的反哺、城市的带动，乡村本身有它独特且越来越弥足珍贵的价值。城市为农村带去资金，农村也为城市提供投资市场；城市为农村提供技术，农村为城市过剩的生产力提供了空间和平台。更为重要的是，农村独特的自然和历史文化价值，为沉沦在物欲中的城市提供了精神依托和心灵的安居之所。乡村培育了光辉灿烂、独具价值的农耕文明，它有“锄禾日当午，汗滴禾下土”的勤劳，有“采菊东篱下，悠然见南山”的恬淡，“桃李罗堂前，榆柳荫后檐”的闲适；这里孕育了人与自然和谐相处的生态体系，它尊山、爱水、有乡愁……我们必须发掘乡村这些价值，展现这些价值，丰富这些价值，乡村完全可以在现代经济体系和现代生活图景中占据重要位置。
理想的生活应该是在城乡之间自由游走，我们期待最先进的技术、最丰厚物质文明与最高远的自然、最悠久历史文明能和谐共生，让人类和自然文明水乳交融，让天人合一超越境界获得新生。');
INSERT INTO shenlun_paper (id, paper_code, title, year, version, question_count) VALUES (31, '2020-ds', '2020年国家公考《申论》真题（地市级）', 2020, '地市级', 1);
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (31, 1, '材料1', '1.本题本由给定资料与作答要求两部分构成。考试时限为180分钟。其中，阅读给定资料参考时限为50分钟，作答参考时限为130分钟。
2.请在题本、答题卡指定位置上用黑色字迹的钢笔或签字笔填写自己的姓名和准考证号，并用2B铅笔在准考证号对应的数字上填涂。
3.请用黑色字迹的钢笔或签字笔在答题卡上指定的区域内作答，超出答题区域的作答无效！
4.待监考人员宣布考试开始后，方可开始答题。
5.所有题目一律使用现代汉语作答。未按要求作答的，不得分。
6.监考人员宣布考试结束时，应立即停止作答，将题本、答题卡和草稿纸都翻过来留在桌上，待监考人员确认数量无误、允许离开后，方可离开。
严禁折叠答题卡！
二、给定材料');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (31, 2, '材料2', '上午9点不到，“老马工作室”的门口已经排起了长队。“我们小区消防栓不出水、电梯天天出故障，您可得给评评理。”“啥情况？你们先说，我记一下。”老马笑着掏出随身带着的笔和本，开始了一天的工作。
老马是街道首席调解员，也是全国人大代表，做了30年的调解工作。“老老少少都叫我‘老马’。去年两会上，习近平总书记也亲切地喊我‘老马’，让我又惊又喜！总书记握着我的手说，老马讲得好，接地气，很结合实际。”老马乐道，“总书记还说，基层工作就是上面千条线、下面一根针，必须夯实基层。我们需要千千万万像老马同志这样的基层干部。”
去年，老马接待群众600多人次，有家长里短，有邻里矛盾，也有基层治理中的一些问题。接待群众是门“技术活”，不仅要真诚待人，还得对政策烂熟于心。“当好基层这根‘绣花针’，状态要投入，本领得过硬，我一天都不敢怠慢。”虽已年过花甲，老马仍每天坚持学习3个小时。30年来，老马成功调解矛盾纠纷2000多起，写了160多本、520多万字的工作笔记。
一天下午，老马接待了一对夫妻，女的一说话就哭起来：“老马，我和他是没法过了。”原来，两人从农村进城打拼多年，生活富裕了，但矛盾也多了。老马一边安抚一边分析：“为什么穷的时候没有什么矛盾，富了反而矛盾多？说明精神贫穷，有短板。”一个小时的交流后，两人带着笑容离开，与来时相互指责的样子截然不同。“时代不一样了，老百姓生活越来越好，大的矛盾冲突越来越少。基层调解，更多的是要做好思想政治工作，做好情绪疏导和心灵抚慰工作。”老马总结道，“我不一定能帮助所有人解决问题，但我要尽最大努力帮大家都解开心结。所有的矛盾，只要用心去调就有解。调解常常不是说服了群众，而是感动了群众。”
老马这根与时俱进的“针”连得巧、织得密、缝得牢。多年来，老马给自己立下了接待群众的24字规矩：起立迎接，请坐倒水，倾听记录，交流引导，解决问题，出门相送。“工作室要成为一个温馨的驿站，群众只要来了，就要努力让大家愁脸进来笑脸出去。”有事没事找老马聊聊的人越来越多，老马总是笑脸相迎。有时，一些群众会问老马：“你是什么职务、什么级别？”“职务和级别都不重要，重要的是——我是你需要的人。”这就是老马的回答。
“我就是想来跟着学、跟着做。”22岁的小温大学毕业后到社区工作，听完老马的一次宣讲后，坚持来“老马工作室”实习。来老马这学习的可不仅仅只有小温，街道的社区综治干部每年都要来“老马工作室”学习一个月以上。老马培养了不少善做调解工作的“小马”。73岁的老党员老齐也经常来工作室找老马，他对老马说：“我年纪比你大，但我也是‘小马’，按照你的方法，我成功劝阻了小区里很多不文明行为呢！”在众多“老马”和“小马”的共同努力下，当地的各种矛盾纠纷逐年减少。
“基层干部就是一根绣花针，要把为群众服务视为终生事业。”老马说，“只要群众遇到困难，问谁是老马的时候，我都会毫不犹豫地站出来告诉他：我，就是老马！”');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (31, 3, '材料3', '午后的阳光洒在脸上，桌上的茶壶里冒着热气。乡干部小雷正坐在村民老窦家里，笑谈两人之前在村子搬迁问题上的那段“不打不相识”的趣事。
这事得从2016年下半年说起。窦家梁这个大山里的村子，土地贫瘠，生存环境恶劣。这里的村民祖祖辈辈守着自己的一亩三分地，种着经年不变的杂粮和谷子，收成常没有保证。村民们看着山下的蔡村靠着红色旅游把日子过得越来越红火，只有眼馋的份。既然一方水土养不了一方人，县里启动了窦家梁村易地扶贫搬迁工程，每户交一万元，搬到山下与蔡村相邻的统一规划的新村。这时，村里突然流传开一个小道消息：村子地底下发现了铝矿，政府要来开采，所以才让大家搬迁，补偿低不说，新村还没个影，有可能连住的地方都没了。在这个闭塞的传统村落里，这样的“消息”很有市场。
假消息的来源，就是老窦。老窦在外打工几年，不但没挣到钱，身体还落下好些个病，回村后不能再干重活，家里还有三个孩子上学。生活压力的叠加，让他脑子不由得“活泛”起来。在听说村子成为当地第一个整村搬迁试点后，他就想：“为什么是我们村？”联想到此前听说附近有铝矿，就发散了自己的思维。
这让包村干部小雷有些猝不及防。此前，大家意见就一个字：“搬！”可这个“消息”，让搬迁工作还没开始，就遇到了下马威。
“白天入户走访，晚上连着开会，村两委一起讨论办法。”小雷那年只有33岁，但这个年轻的乡镇干部脸上却比同龄人多了好几道皱纹，“我也很奇怪，本来说得好好的，怎么大伙突然就变卦了。”多方询问，小雷才知道铝矿的说法出自于老窦。“那天晚上正在开会，他就不请自来了，我也正在火头上。”两人吵了一架。
“那天最后还是没说拢，老窦吵着要我保证能住进新房，还让我写保证书，盖‘红戳戳’，可那会儿搬迁政策还不明朗，我也不敢啊！后来想想，说到底是信任问题。”小雷说，“怎么解决？只有让事实说话。那时几乎天天催跑各种建房手续。”真正让老窦和村民们吃下定心丸的，是山下的挖掘机开始“轰隆隆”地平整土地，这意味着新村已经开建。伴随着机器声，这个山里的汉子红着脸在小雷面前搓着手：“前面的话就当我瞎说。”
但问题还没结束。2017年下半年，山下的新村就快建成了，好事将近，可村里人又犯起了嘀咕，搬进什么样的新居成了焦点。
“有的家里四口人，我家是五口人，可住的一般大，这不公平。”老窦说。这回小雷没跟他吵，事实上，通过上回合交锋，两人关系还有点升温。可在这问题上，老窦半点不含糊。小雷把当初的规划、各家人口数和老屋面积都拿出来：“你看，咱们就是这么块地，建再大的条件也不允许。再说，新村是按村里的实际情况统一规划和设计的，房子面积主要和老屋相应，人口数不是决定因素。这些事先也都公示过了。”在事实面前，老窦算是无话可说，可他又提出另外一个问题：“大家都养着牛、羊，现在要搬迁，可还不到每年牲口集市的时间，卖又卖不出去，你让这些牲口去哪？”小雷又被问个措手不及。当晚，他仔细翻阅了县里的易地扶贫搬迁条文，“人、钱、地、房、树、村”，都有明确办法，但没有一条跟牲口有关。第二天一早，他就去县里反映情况，县长很重视，特意召集人员开会，商讨出了一个解决办法：牲口也给补偿费。
2018年12月，村民们陆续搬进新房。小雷长舒一口气，有一种胜利的喜悦。可这种喜悦还没持续几天，他就被十几个村民堵在了办公室门口。大伙七嘴八舌地说起来：“马桶不好用”“电视没法看”……习惯了山上生活的人们，搬入现代化设施齐全的新居后，不适应的状况五花八门，小雷都耐心地一一解答。
送走了这些人，楼道里闪出那个熟悉的人影。老窦冲着他嘿嘿一笑：“他们来可不是我的主意，咱俩这交情，我会因为这些找你吗？”小雷知道他想什么：“你不就是担心不能种地以后怎么办吗？前段时间村里申请了3个护林员指标，你是贫困户，又干不了重活，村里已经推荐你担任护林员了。不光是你，县里开展的护工培训和扶贫车间招工，咱村人都能沾上光。咱村离蔡村近，蔡村的旅游还可以带动咱村的发展。”
老窦笑了。几次接触，他发现，小雷是个值得交的朋友。过年时，小雷来老窦家拜年，两人搂着肩膀有说有笑，哈哈一乐，往事都付笑谈中。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (31, 4, '材料4', '在锦林区社会治理综合指挥中心，一块巨大的显示屏实时显示着交通、餐饮、环境等领域的几十个监控场景，每个场景的运行都配有详细的数据和指标。这个集管理、执法、服务为一体的“智慧锦林”综合平台，是锦林区社会治理的中枢神经。它可以通过网格巡查、视频监控、无人机巡防、移动终端接受举报等多种手段，对公共秩序、公共环境、公共安全等相关问题进行巡查，“触角”延伸至辖区的每一个角落。
“触角”的末端，除了智能设备，既有各部门下沉到基层的工作人员，也有街道社区干部、网格管理员，还有使用专门APP的每一位市民。区委李书记介绍，通过“智慧锦林”综合平台，锦林区打造了部门联动、街道配合、群众参与的机制，实现了以指挥中心为圆心，以网格责任体系为基础，以全方位快速响应队伍为力量的社会治理共建、共治、共享新格局。
专门的APP里面，设置有水、电、气、物业等多种生活缴费功能，并提供养老金、老年证、低保申请等常用便民服务咨询与网上办理服务。在“锦林群众”栏，设有“你是我的眼”平台，提供违法、违规及扰民行为的举报渠道及奖励方式；而在“政民互动”栏，则有市民关于入学、物业、环境卫生等各方面的诉求，以及相关单位的具体答复和联系人等内容。指挥中心王助理介绍，在平台上，大到环境整治、食品安全、治安防控、物业纠纷，小到车辆违停、占道经营等各类杂事烦事，群众都可以上来反映，通过APP实现信息源头全覆盖。
网格员童大姐每天都会巡察自己负责的网格，并上报各种情况。通常情况下，这些事由网格员自己发现并处理。“在我们这儿，小事不出网格，大事不出社区。”童大姐自豪地说，“网格员就像社区客服，有求必应。我处置过群租扰民、违规占道等好多事情，也举报过安全隐患、河道污染等问题。”像童大姐这样的网格员，在锦林区共有五百多名。这是一支充分发动各社区党员、志愿者，按照“一格一员”原则组建的专兼职队伍。“主动发现的问题多了，市民的投诉也就少了。”王助理说，“平台上70%的问题信息是由网格员上报的，问题隐患可以在第一时间发现、处置、解决，提高了源头发现和前端处置能力。”
初夏，新开业的德嘉酒店将空调外挂机组安在锦绣小区绿地，噪音扰民严重。居民举报当日，酒店经理满口答应整改，却迟迟未见实际行动。举报的第四天，指挥中心启动共治机制，通过平台通报，区综合执法局、园林局、派出所和街道办事处等组成联合执法队，进行联合执法。在处理现场，联合执法队查看了酒店规划设计图，指出“空调外挂机组占用绿地并不在规划之中，属非法占用绿地”，责成其立即整改。经过一个月的施工，原本想拖过夏季再做改造的酒店方将机组搬到了酒店楼顶。
“办案中，3天内属于社区端自治机制，尽力将问题在社区、网格员、居委会、物业、业主委员会协同自治层面处置。对于自治无效的，4天后启动‘大联动’执法共治机制，打破了社区工作人员单打独斗处理问题的困难局面。”社区马书记说，“过去解决这些难题时，协调过程复杂、耗时长，现在通过综合平台的应用，实现了‘平台一吹哨，大家来报到’的智能化联合管理。”执法中队队员小方同样也感受到了变化：“现在和‘大联动’小分队一起处理案件，执法过程顺利多了，也能实实在在帮老百姓解决问题。”
“2018年，我们经过对举报数据的长期观察，发现餐饮行业的油烟污染是市民反映的热点、难点问题。”王助理说。研判数据提交后，区政府多次召开专题会议研究部署，在餐饮行业集中的街道，开展绿色餐饮示范街区建设。“在综合平台，大数据的运用无处不在。针对居民诉求较多的问题，指挥中心工作人员定期分析研判，为政府提供决策依据。”区综合执法局吴局长说。平台借助视频天眼系统，利用1000多个摄像头对重点区域进行不间断监控，抓拍采集油烟污染线索，及时取证，第一时间将数据下派执法队员查处。此外，还利用无人机反应迅速、覆盖范围广、无死角监控等特点，对餐厨油烟、焚烧垃圾、锅炉黑烟等问题进行空中取证，形成了平台化、科学化、效能化的管理与执法常态，有效解决了空气污染环境违法难管、难罚的问题。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (31, 5, '材料5', '2019年年初，沙洲市启动城区农贸市场的改造升级工作。针对不同的市场现状，改造升级怎么进行更切合实际？为此，沙洲市市场服务中心调研走访了几个市场。
先把镜头对准莲池农贸市场，这个市场有40年的历史了，附近的社区从一个发展到七八个，居民从千把人变成四五万人。随着周边居民的大量增加，市场脏乱得不成样子。“过道没两尺宽，并排都站不下两个人，买菜要侧着走。有时大夏天实在受不了，宁可走老远到一家超市买菜”。居民刘阿姨说。市场管理员最怕春夏之交：“下大雨，水一下子能积二三十厘米深。还有，消防设施配备也不全，存在安全隐患。”摊主王女士也愁，菜摊旁有条水沟散发着异味，市场内空气流通又不畅，顾客经常一边挑菜一边捂着鼻子，她不得不找木板盖着。
莲池街道办事处廖主任认为，老市场虽然问题多，但是居民有需求，搬不走，拆除重建代价又太大，最合理的办法就是对准问题改造。他说：“改造期间，老市场得关门施工，几万人的‘菜篮子’不管不顾可不行。改造之前有准备，改造当中才好应对。”市场管理员提议：“要不先找个地方过渡一下。”居民刘阿姨对“过渡”有点担心：“那下雨天买菜方便不方便？卫生还有没有人管？”摊主王女士考虑的是：“在这里做了几十年生意，就在一个位置上没动过，老顾客都熟悉，如果进行改造，工程完工后，还能不能重新回到老地方？”
镜头摇到豹岭农贸早市。摊贩周大姐一早就来到处于小巷子的早市卖菜，5点半开始，8点就得收摊。她打比喻说：“我就是个‘流浪’的摊贩。”“早市起先只有周边的菜农卖自产蔬菜，后来逐步有一些外来摊贩加入。考虑到确实能解决居民的买菜难题，社区一开始默许了其存在，只对开市闭市时间稍加限制。”豹岭社区党支部范书记介绍。几位居民代表也一致抱怨：“每天早上，摊贩们将小巷堵个严严实实，出行极不方便。”“大清就吵吵闹闹，觉也睡不好。”
社区深感为难。直接禁止，太粗暴；开了口子，管理力量又跟不上。“有时候八点已过，摊贩还不愿意走。”城市管理大队副大队长说，“我们和社区工作人员去管，摊贩们就一哄而散，人一撤，他们又继续贩卖。”“过去几年，社区周边的楼盘如雨后春笋般建起，人口激增，买菜的需求越来越多，之所以流动摊贩多、临时市场乱，恰恰是因为缺少规范稳定的农副产品交易场所。”范书记建议，“这附近有一片闲置老厂房，是不是可以盘活起来做点文章？”
镜头转到沙洲市中心最大的农贸市场——月湖市场。这个市场各个道口没有设置栏杆，加上停车坪被货物堆满，更显得拥挤不堪。“经营户的手推车、三轮车，居民的电动车、自行车，通通往市场里扎。”居民张大妈说，“占道经营也很普遍，经营户的纸箱、塑料筐，全扔在过道上。”沙洲人喜好买活禽，但活禽是月湖市场环境污染的主要来源。如果直接取消活禽供应摊位，居民大多不同意，经营户也很难接受。参加调研走访的丁工程师在实地考察后指出：“目前活禽摊位的存放、宰杀和售卖三位一体不够科学，通风也不顺畅，这些都是造成污染的重要原因。”
“月湖市场本身建筑设施比较齐全，硬件上施工不需要伤筋动骨，只要预先做好安排特别是安全防范，完全可以就地边营业边整改。”月湖街道办事处李主任说。他认为，市场改造为的是利民、便民，相比于“一刀切”，还应该寻找更好的办法。“即使是改造提升后，管理也不只是政府部门和市场管理方的事，消费者和经营户，都是参与主体。要走出‘治理一变乱一再治理’的循环，还得在制度层面上下功夫。”');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (31, 6, '材料6', '莱康村所在的M市位于沿海地区的S省，各项改革都走在前面。“伴随着率先发展，新问题、新矛盾更加突出、更加集中。如果老是跟在后面，像消防队一样到处救火，难免疲于应付、效果不佳。”M市市委孙书记说，“面对这些难题，亟待探索既能解决短期现实问题，又能兼顾长效公平的乡村治理新模式。要想建设更加富有活力的乡村，就得聚焦如何减少矛盾、化解矛盾，乡村治理也不能再‘单兵作战’，而应‘联合出击’，从以行政管理为主要手段向行政、法律、道德等手段的综合运用转变。”
走进莱康村，绿树成荫，鸟语花香，街道平坦干净，草地绿林中矗立着一幢幢红瓦白墙的乡间别墅，到处呈现出一派欣欣向荣的景象。“要知道，莱康村过去可是个有名的问题村，基层组织软弱涣散，人心也是出了名的不齐，打架斗殴事件特别多。特别是早些年，由于征地补偿问题，小吵小闹天天有，大吵大闹三六九，几乎每天都有村民挤在村委会里争吵。村里吵不出结果，不少村民还去省里讨说法。”村党支部陈书记感叹，“更让我记忆犹新的是，7年前我刚当书记时，由于以前村集体资产严重流失，村里的账上只有2.4元。”
给钱给物，不如建个好支部。在镇里的支持下，莱康村狠抓村党支部班子自身建设和党员队伍建设，配备了一批有能力、有威望的村民担任村两委委员。新班子把中心工作放在村民最关注的问题上，重新核查低保、危房改造、临时救助等惠民项目，全力解决影响团结和谐的问题；积极争取补助资金，整治村容村貌，完善水、电、路等基础设施；开展绿化亮化、厕所革命、清理违章建筑等项目。这一系列举措，使莱康村逐步树立起崭新的形象。
“我们通过各种办法努力做到让村民满意，让组织放心。”陈书记说，“但要建设美丽乡村，光靠我们干不行。村里的事还是得村民说了算。”在村党支部的引导下，莱康村成立了村民理事会，让村民主动参与到村庄事务的管理与决策中来。今年年初，为落实村企攻坚项目的规划建设，村民理事会一直积极跟进，到每家每户积极宣传农村集体产权制度改革政策，就如何成立合作社、如何分红、土地流转定价等细节广泛征求意见，得到了全体村民的支持。
如今，村民理事会又充实了部分企业代表、下乡市民代表到理事会中来，共同参与、协调村级事务，重大事项均通过村民理事会与村民广泛沟通，取得良好效果。
莱康村今年还从村组干部、老党员、致富能手、退伍军人、法律工作者、法律志愿者中选取一批政治素质好、宣讲水平高的村民，进行重点培训，引导他们主动担任“法律明白人”的带头人，充分发挥他们在宣传政策法规、化解矛盾纠纷中的示范引领作用，推动莱康村形成了遇到问题找法、解决问题用法、化解矛盾靠法的良好氛围。
由村里老党员、老干部和村民小组长等组成的文明评判团，深入发掘“老莱康风骨”的村民道德规范，通过修订村规民约，规范村民行事规则。文明评判团挖掘祠堂、故居、牌坊、族谱中的家风家训资源，搜集整理了全村20多个姓氏的家规家训，并把这些做成门牌，用以打造“家风家训示范街”。用陈书记的话说，“在村里，随便走走都能受到熏陶”。在文明评判团的主持下，莱康村年年评选“最美家庭”“孝德人家”，为模范树榜，助家风传扬。村里还陆续组建了篮球队、腰鼓队，每年举办农民文化体育节。通过这些活动，村民的生活充实了、心拉近了，很多积怨矛盾在无形中得到了化解。
这些年，在村两委的带动下，莱康村盘活土地资源，引进优势企业，成立养殖合作社、种植合作社、林业合作社等，逐步滚动壮大村集体经济的“雪球”。2018年，莱康村集体经济收入达到1000多万元。收入多了，村民的生活过得越来越好。“经过大家这么多年的努力，我们有信心奔向更加美好的生活。”陈书记对莱康村的未来充满自信。
从曾经的问题村，到如今的和谐村，莱康村这些年的发展实践，为新时代的新农村建设写下了生动注脚。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (31, 3, '三、作答要求
根据“给定资料1”，请你谈谈老马是怎样“当好基层这根‘绣花针’”的。（10分）
要求：全面、准确、有条理。不超过200字。
“给定资料2”反映了乡干部小雷在窦家梁村易地扶贫搬迁过程中遇到的一些问题，请你谈谈他是如何解决这些问题的。（15分）
要求：内容全面，条理清晰。不超过300字。
邻区有关部门准备到锦林区学习考察，了解“智慧锦林”综合平台在社区治理方面的特点和运行情况。如果你是锦林区负责接待的工作人员，请根据“给定资料3”，写一份情况介绍提纲。（20分）
要求：要点完整，内容具体，条理清晰。不超过500字。
如果你是沙洲市市场服务中心工作人员，请根据“给定资料4”分别梳理三个市场存在的问题，并提出相应的解决措施。（25分）
要求：
（1）问题梳理全面、准确；
（2）所提措施有针对性、切实可行；
（3）不超过500字。
近期，S省开展乡村治理先进典型评选工作。M市打算推荐莱康村参加评选，如果你是该市有关部门的工作人员，请根据“给定资料5”写一份莱康村参评的推荐材料。（30分）
要求：
（1）紧扣资料，内容全面；
（2）逻辑清晰，语言准确；
（3）字数800～1000字。
2020年国家公考《申论》真题（地市级）（解析）', 10, 200, '3.向上级申请，给予补偿。翻阅条文无果后马上向上汇报，引起县里重视，给养殖业补偿，解决养殖业搬迁难题。');
INSERT INTO shenlun_paper (id, paper_code, title, year, version, question_count) VALUES (32, '2020-sb', '2020年国家公考《申论》真题（副省级）（网友回忆版）', 2020, '省部级', 1);
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (32, 1, '材料1', '1.本题本由给定资料与作答要求两部分构成。考试时限为180分钟。其中，阅读给定资料参考时限为50分钟，作答参考时限为130分钟。
2.请在题本、答题卡指定位置上用黑色字迹的钢笔或签字笔填写自己的姓名和准考证号，并用2B铅笔在准考证号对应的数字上填涂。
3.请用黑色字迹的钢笔或签字笔在答题卡上指定的区域内作答，超出答题区域的作答无效！
4.待监考人员宣布考试开始后，方可开始答题。
5.所有题目一律使用现代汉语作答。未按要求作答的，不得分。
6.监考人员宣布考试结束时，应立即停止作答，将题本、答题卡和草稿纸都翻过来留在桌上，待监考人员确认数量无误、允许离开后，方可离开。
二、给定材料');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (32, 2, '材料2', '在中国特色社会主义进入新时代、决胜全面建成小康社会、开启现代化新征程的大背景下，把各方面优秀人才团结凝聚到党和国家的事业中来，显得比以往任何时候都更加重要和紧迫。习近平总书记明确要求“在知识分子和广大人才中大力弘扬爱国奉献精神，激励他们的爱国之情、报国之志。要加强对人才的政治引领，做好各类人才教育培训、国情研修等工作，增强他们的政治认同感和向心力，实现增人数和得人心有机统一”。
L省是经济大省、人才大省、开放大省，遇到的矛盾问题更早更多。面对一系列难题，L省以习近平新时代中国特色社会主义思想和习近平总书记关于人才工作重要论述为指导，紧紧围绕“实现增人数和得人心有机统一”的总目标，探索出了一条对人才的政治引领实效化的新路径。
L省始终坚持党管人才这一根本原则，着力构建权责明确、务实管用的组织架构。坚持一把手抓、抓一把手，省委书记批示要求“认真落实党的知识分子政策，加强政治引领”，各级党委（党组）都把加强对人才的政治引领作为“书记项目”。2018年，L省调整了机构布局，进一步整合了人才工作的相关力量，明确了对人才的政治引领职能职责。
L省把习近平总书记关于人才工作重要论述作为人才培训的第一课，引导广大人才同党中央保持高度一致。通过实施“爱国、奋斗、奉献”精神教育三年行动计划，引导广大人才树牢“四个意识”、坚定“四个自信”、做到“两个维护”；通过常态化组织人才赴井冈山、遵义等红色教育基地学习，让广大人才在切身感受中提高对世情国情党情的认识，坚定理想信念。
此外，全省集中举办高层次人才“爱国、奋斗、奉献”精神主题学习会，邀请省委讲师团专家作报告。学习会上，为高层次人才颁发证书、授予奖牌，增强其荣誉感和成就感。会后，制作主题学习会视频，放大典型示范效应。同时，开展“身边的榜样——知识分子群像群塑”活动，分层分级分类别，评选出一批可看可知、可比可学的先进典型，通过榜样的力量感召广大人才投身全省建设。
L省积极响应“一带一路”、脱贫攻坚等国家战略和重点工作，动员人才开展对口帮扶、对口支援。仅2018年，全省就选派各类人才3109名到对口帮扶地区服务锻炼，并依托博士服务团计划，选派经济金融、医疗卫生等领域博士教授16批140余人次，到西部地区和革命老区援助帮扶，让人才在祖国最需要的地方绽放青春、追逐梦想。
感情亲近，思想才能贴近。L省建立健全专家联系制度，各级班子成员、部门党委（党组）书记分别结对联系一批专家教授、名医大师、技术骨干，形成横向到边、纵向到底的工作机制。各级党组织坚持“四必访两必到”，在重要节日、专家取得重大成就时、逢十生日、罹患重大疾病时领导干部必访，逢年过节、逢有喜事时问候祝福短信必到。注重“关键小事”，以周到贴心的服务把专家人才紧密团结凝聚起来。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (32, 3, '材料3', 'M农场成立于2015年，是一家将生态稻田和人工智能相结合的高新技术企业。它所研制的“胚芽米”，是一种在稻谷加工过程中保留其胚芽部分的精制米，比普通大米含有更加丰富的维生素B族和微量元素。创始人小李的初衷就是希望越来越多的老百姓能吃到更有品质的大米。
创立之初，M农场就将人工智能引入水稻种植阶段。小李说：“传统农业，往往包含着最苦、最累、最费人工的劳作过程，我们希望通过高科技为传统农业增效。”他算了一笔“人工账”：以人工巡田、除草为例，传统农业中，高质量的巡田速度为每人每天50亩到80亩，一季稻田需巡田130天；每人每天人工除草约1.5亩到2亩，一季稻田需除草3至4轮。小李表示，这样的方式费时费力，即便给每亩稻田提供1000元人工费，也还是没有人愿意干。为了改变这一困境，M农场使用田间机器鸭代替人来巡田、除草，效率提高300%，成本降低50%。
此外，M农场还使用物联网技术及田间智能机器对生态水稻数据进行全方位监测和采集，由专家团队进行建模及大数据分析，进行人工智能海量数据训练，深度挖掘水稻生长全过程数据，进行图像识别，建立水稻最佳生长模型，实时生成稻田长势及病虫害的可视化智能管理界面，提供病虫害防治指导、作物保护方案，实现了生态农业无人化、智能化管理。
M农场在种植全过程中不使用任何化学农药、化肥、除草剂，而采用生物制剂、有机肥，以确保大米的食用安全和营养价值。以生态稻田为基础，M农场引入旅游、文化、艺术等多元化产业。小李说：“我们打造共享农场、田园综合体，吸引旅客来体验田园生活。我们还挖掘稻米文化，通过自然课堂为孩子们讲述‘一粒米的旅行’。农场美丽的田园景色，吸引着一批又一批的人来到这里摄影绘画写生。”如今，“稻田上的艺术节”“稻田上的自然课堂”“稻田上的露营节”，种种衍生产品，不一而足，给M农场带来更多的发展机遇。
小李表示，当下的农业，正逐步走出传统模式，已不再是单纯的第一产业。在M农场，“一产”实现种植标准化、人工智能化等有机生态种植，“二产”实现胚芽米、胚芽米食、乡村手工艺等与胚芽米生产有关的加工，“三产”实现休闲观光、户外活动、宜居养生、精品民宿、乡村艺术等稻田上的系列自然体验。M农场以生态水稻种植为基础，实现“一二三产业”高度融合发展，力图打造新型全产业链模式。
目前，M农场拥有60多位员工，平均年龄只有27岁，他们是农场培养的一批知识型、技术型“新型农民”，是创业生力军。M农场也成为青年人发展新型农业、改变乡村的青春舞台。“70后怕种田，80后不愿种田，90后不提种田”是网友的调侃，也是部分事实。小李坦言，农业的形象一直是劳作辛苦而收入低，很难吸引年轻人，而一个没有年轻人加入的行业，是没有未来的。“让农民成为令人羡慕的职业”是M农场努力的目标之一。在M农场的示范和带动下，如今更多农民和返乡青年愿意扎根农村，做新型农民，发展新型农业。
今年年初，小李被评为省级杰出创业青年。颁奖礼上，小李说：“乡村振兴，是农业强、农村美、农民富的全面实现。M农场是乡村振兴战略的实践者和受益者。新时代的创业者，一定要有社会担当，要做些对国家和社会发展有意义的事情。”');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (32, 4, '材料4', '2019年3月，G省启动“专家助力脱贫攻坚服务团”第三期工作。本期由4名成员组成脱贫攻坚队，驻帮扶对象W县一年，全面助攻脱贫攻坚。脱贫攻坚队成员如下：
队长小陈，男，31岁，G省就业管理局工作人员；王老师，男，28岁，Z大学教育学院教师；马医生，女，29岁，G省第一人民医院医生；张主任，男，30岁，田地农业科技有限责任公司技术专家。
驻县的第一周，小陈带领3名队员深入方方面面走访调查，以下是他的调查日志内容。
2019年3月11日周一
今天是驻县的第一天。上午，我们与李县长会面，他介绍了W县的基本情况：W县地处G省中部，县域面积2065平方公里，总人口34.5万人，其中农业人口32.2万人，共辖12镇4乡217个行政村。该县共有贫困户1.73万户，贫困人口7.45万人，贫困面21.59%，是G省深度贫困县之一，脱贫攻坚任务十分艰巨。
下午，我召集队员开了碰头会，让大家谈谈各自想法。王老师想重点关注教育问题，他说：“扶贫先扶智，让孩子们接受良好教育，是阻断贫困代际传递的重要途径。”马医生想重点关注医疗问题，她准备先从县医院着手了解情况。张主任是农业技术专家，他告诉我们，W县素有“中国马铃薯良种之乡”之称，他想重点关注农产品种植及深加工方面的问题。而我想重点关注一下县里的就业问题，“授人以渔”才能真正帮助贫困户过上好日子。
2019年3月12日周二
上午，我们一起去了北寨镇。W县真是个神奇的地方！奇特的地形地貌和特殊的气候条件造就了如画般的自然景观。有高山，有森林，还有水系，自然风光非常美丽。把绿水青山变成金山银山，将丰富多彩的自然风光与脱贫攻坚工作结合起来，对县里的脱贫工作乃至未来的长远发展都会起到很大作用。
下午，我和马医生去了县医院。县医院的门诊大楼刚翻新，就医环境看起来还不错，但进一步走访发现，医疗设备陈旧老化，像B超机、核磁、CT这类设备已多年没有更换过。比起设备，人才短缺、技术落后是更大的问题。医院乔院长说：“两年来只招到两个人，上个月还走了一个，去了省里的大医院。招不到人便没有办法提升技术。无法提升技术，便没人来看病，更留不住人才。”但我们了解到，该院新招的医务人员，每月工资有六七千元，对于一个贫困县来说，这样的工资并不算低。可为什么留不住人呢？乔院长告诉我们，这与医生自身职业发展的特点有关。医生技术的进步需要不断地学习，只有接触更多的患者，见识更多的病例，才能让自身医术不断提高，解决更多疑难病例。而只有大医院才能给予这样的成长机会和平台。
从县医院出来，我们去了贫困户老杨家。“别人拿钱供孩子读书，我是拿钱供孩子看病。”这是老杨对我说的第一句话。原来，老杨大儿子患有重度糖尿病，大部分时间在病床上度过。“在县医院治疗效果不怎么好，可又没钱带他去大医院看，只有先吃药维持吧。”老杨说，“今年我种了不少香菇和羊肚菌，等多攒些钱就带儿子去外地看病。”
2019年3月13日周三
今天，我和王老师与县教育局刘局长一起去县城的育红中学考察。去的路上，刘局长告诉我们，专任教师数量不足、整体素质不高是当前的大难题。
育红中学算是W县教学条件比较好的学校了，但是学校除了购置必需的教学、办公用品来维持正常的教学工作外，已无能力添置电教设备、教学挂图、投影仪等教辅设备，学校连一个图书室都没有。教师们知识结构老化、教学方式陈旧。面对课改的新要求，他们明显力不从心，更谈不上运用现代化教学手段了。由于经费紧张，老师们也没有参加业务培训和到外地听课学习的机会。育红中学黄校长说：“教学条件差、待遇低，难以吸引优秀人才来任教。没有人才，就难以提高教学水平，这是个恶性循环。”
2019年3月14日周四
这几天，张主任跑了好几个镇，走访了几家企业，深入了解W县产业发展的状况。张主任告诉我们，马铃薯、中医药、食用菌是县里三大优势产业，已初步形成主导产业雏形，但产业布局零星分散，基础设施建设严重滞后，没有形成区域发展、规模发展，产业集中度不高。全县产业发展的科技支撑体系还不健全，特别缺乏科研技术人员。
下午，我和张主任一起去了马铃薯种植基地。基地负责人说，现有产品仍以初级产品为主，缺乏深加工增值，没有形成品牌效应，导致市场竞争力弱，盈利能力不强。由于缺乏技术专家指导，村民在种植过程中遇到的问题经常得不到及时解决。
2019年3月15日周五
一大早，我和张主任去了一家食用菌生产企业，就是收购贫困户老杨种植的香菇和羊肚菌的那家。这家企业的吴经理告诉我，县政府去年就想把三家食用菌生产企业整合起来，打造一个食用菌产业园区，可迟迟没有落地。人手不足是一大难题，很多种植农户都外出务工了，留在家的又缺乏种植技术。回来的路上，我琢磨着，要是能将无法外出务工的贫困人员吸引到食用菌产业园区中来，让村民“不出村、有活干、把钱赚”就好了。
下午，队员们聚在一起，商讨如何利用自身优势，开展后续扶贫工作。经过一周的走访调查，大家更加坚定了打赢脱贫攻坚战的信念与决心。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (32, 5, '材料5', '为了促进快递配送从业青年的职业发展和社会融入，共青团H省委邀请了部分省人大代表、省政协委员，走进快递企业开展调研，并与企业代表、从业青年代表等进行座谈交流。以下是座谈时所收集到的部分资料。
共青团H省委权益部部长：习近平总书记明确要求共青团主动关注、积极联系、有效覆盖快递小哥等新兴青年群体。为了解并解决快递配送从业青年在职业发展和社会融入方面面临的一些问题，今年年初，我们面向这一群体开展了一次问卷调查。
结果显示，受访者中，每天工作时间超过8小时的占88.32%，其中工作8-10小时的占31.79%，工作10-12小时的占27.66%，工作12小时以上的占28.87%；每月休息时间不超过4天的占94.84%，一天都没休息的占25.09%。
有受访者表示，当前大部分快递公司制定了完善的用工制度，但仍有一小部分快递公司存在规避劳动法、不与员工签订劳动合同等问题。受访者中，没有与公司签订劳动合同的占6.74%，与公司签订劳动合同期限为1年的占60.52%，签2年的占22.33%，签3年及以上的占10.41%；从事快递工作的时间不足1年的占48.0%，工作1-3年的占32.6%，工作3年以上的熟练工仅占19.4%。
关于职业发展，有47.15%的受访者表示所在快递公司职业发展通道设置不合理，而在这些受访者中，有60.5%的人表示不愿意在公司继续工作，有“跳槽”意愿；在社会融入方面，20.79%的受访者表示城市归属感差，身在城市却无法融入城市。
解决快递配送从业青年面临的问题，需要社会各方的关心支持，需要各位人大代表、政协委员的建言献策。
快递人员代表：我今年22岁，来公司有一年了，每天都处于“抢时间”的状态。上个月在派送中和一辆面包车发生了擦碰，幸好人没事，可是误点导致客户投诉，公司扣了绩效，结果一天就白干了。这种事，在同事身上也常有发生。借着这次机会，我想建议公司确定更加合理的配送量、送达时间和薪酬标准，不能“以罚代管”。我喜欢我工作的这座城市，想留下来和这个城市的青年们一样，努力奋斗，创造美好生活。可是，每天“累得下班就想睡觉”的工作压力，让我没精力参与正常的社会交往、体验这座城市的美好。我感觉，我始终像一个过路人。
某快递企业负责人：公众对快递人员的辛苦和安全风险缺乏了解，对他们不够尊重、理解与认可。有些地方，甚至存在客户辱骂、敲诈快递从业人员的问题。这些都导致快递人员离职率很高，我们的用工成本也随之提高。
省人大代表A：经过这次调研，我们对快递人员的劳动保障、安全风险和权益保护等问题有了更深入的了解。我们会建议相关部门统一快递人员的职业准入和培训标准，对快递人员的业务水平、职业素养等加以提高。快递企业也要给快递人员提供发展通道和晋升平台，让他们有盼头。
省政协委员B：大多数快递小哥缺乏应有的保障，要想办法减轻他们的生活压力。还要提升公众对快递小哥的理解和尊重，让他们工作得有尊严、更体面。我们会呼吁全社会进一步关注快递小哥面临的诸多问题。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (32, 6, '材料6', '2019年4月，S省省委人才发展局在外省某高校举办引进高层次人才政策宣讲会。宣讲会吸引了来自全国各地的1000多人参加。
刚从国外归来的医学博士小田就是此次参会者之一。S省优美的环境、清新的空气、便利的交通、广阔的前景都吸引着她，使她对宣讲会充满着期待。
小田一早便来到会场，在入口处，她收到了工作人员发放的一本《S省引才政策选编》。小册子的首页写着：栽下梧桐树，引得凤凰来。入座后，小田翻开小册子，仔细阅读起来：
●S省坚持把人才作为第一资源，以习近平总书记关于人才工作重要论述为指导，加强全省人才工作顶层设计和制度安排。以制定实施《百万人才进S省行动计划（2018-2025年）》（以下简称《行动计划》）为主要抓手，不断创新人才引进培养机制，实行更加积极、开放、有效的人才政策，向国内外优秀人才敞开最热情的怀抱。《行动计划》明确，从2018年至2025年，S省将引进各类人才100万人，并从4个方面提出30条含金量十足的政策，不断完善人才引进、管理、评价、流动、激励、保障等领域的制度体系，为广大人才来S省干事创业提供有力的制度保障。
●《行动计划》出台后，S省全面梳理现有人才政策，制定了一批急需政策，调整了一批过时政策，逐步建立健全人才制度体系。特别是在人才服务方面，制定出台了《关于引进人才住房保障的指导意见》《S省高层次人才子女入学实施办法》《关于引进高层次人才配偶就业安置实施办法》等制度，基本形成覆盖人才落户、安居、购房、购车、子女入学、配偶就业、医疗保障、出入境、居（停）留等全方位的人才服务保障政策体系，着力解除人才来S省就业创业的后顾之忧。
●以新一轮党政机构改革为契机，S省成立省委人才工作委员会，加强对全省人才工作的宏观指导、科学决策、统筹协调和督促落实，着力提升人才工作地位；组建省委人才发展局，并加挂省委人才工作委员会办公室牌子，进一步整合人才工作相关力量，统筹全省人才政策、项目、资金、力量等资源，建立起统一高效的党管人才领导体制，用前所未有的力度推进招才引智工作。
翻看完小册子，小田注意到了会场左侧的展板。她走到展板前，看到展板上列出了S省针对高层次人才制定的重点项目——大师级人才、杰出人才引进计划。该计划聚焦航天领域重大科技创新基地、国家深海基地南方中心、国家南繁科研育种基地、国家热带农业科学中心、全球动植物种质资源引进中转基地5大平台，以及教育、医疗、科技、文化等重点领域，积极推动高校、医院、科研院所、企业等用人单位引进大师级人才、杰出人才。人才来省后可以直接纳入省委联系服务重点专家范围，享受免租金、可拎包入住的人才公寓；在薪酬待遇、科研资助等方面，采用“一人一策、一事一议”的方式给予支持。同时，鼓励用人单位采用年薪制、协议工资制的方式提供报酬，并配备工作助手。对于大师级人才、杰出人才领衔的团队式引进，S省将集中政策和财力给予重点支持。
正看着展板上的内容，一阵优美的旋律吸引了小田的注意。此时，会场前方的屏幕开始播放宣传片。“改革的动力、创新的活力，正让我省穿山越水一路向前，让每一个梦想都有生长的土壤，让每一种奋斗都有驰骋的天空。你的舞台就在眼前，在这里，你的未来更加精彩！”时长8分钟的宣传片让在场的所有参会者充分感受到了S省的魅力。
宣传片播放结束后，宣讲会正式开始，S省省委人才发展局有关负责人发表了热情洋溢的推介讲话，向广大优秀人才发出诚挚邀请。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (32, 3, '三、作答要求
根据“给定资料1”，请你概括L省在人才的政治引领方面的主要举措。（10分）
要求：全面、准确、有条理。不超过200字。
“给定资料2”中，M农场的案例为新时代青年创业提供了哪些启示？（15分）
要求：分析全面，条理清晰。不超过300字。
假设你是队长小陈，请根据“给定资料3”提供的调查日志内容，拟定脱贫攻坚队下一步工作的主要任务及措施。（20分）
要求：要点完整，措施具体，条理清晰。不超过500字。
调研结束后，共青团H省委拟起草一份关于促进快递配送从业青年职业发展和社会融入的调研报告。假设你是该调研组成员，请根据“给定资料4”，撰写调研报告中“问题”与“建议”这两部分内容的提纲。（25分）
要求：
（1）问题梳理全面、准确；
（2）所提建议有针对性、切实可行；
（3）不超过500字。
假设你是S省省委人才发展局的工作人员，请根据“给定资料5”，以“海纳百川聚四方之才”为题，为S省省委人才发展局有关负责人撰写宣讲会上的推介讲话稿。（30分）
要求：
（1）角色定位准确；
（2）内容切合主题；
（3）语言流畅，有感染力；
（4）字数800～1000字。
2020年国家公考《申论》真题（副省级）（解析）', 10, 200, '3.优化企业管理。加强对从业者的业务培训；完善晋升机制，提供畅通的职业发展通道；合理制定薪酬标准、绩效考核体系。');
INSERT INTO shenlun_paper (id, paper_code, title, year, version, question_count) VALUES (33, '2021-fs', '2021年国家公务员考试《申论》真题（副省级）', 2021, '副省级', 8);
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (33, 1, '材料1', '1.本试题由“给定资料”和“作答要求”两部分构成。考试时限为180分钟。其中，阅读给定资料参考时限为50分钟，作答参考时限为130分钟。总分100分。
2.请在题本、答题卡、草稿纸指定位置上用黑色字迹的钢笔或签字笔填写自己的姓名和准考证号，并在答题卡上用2B铅笔将准考证号对应的数字涂黑。
3.请用黑色字迹的钢笔或签字笔在答题卡指定的答题区域内作答，超出答题区域的作答无效。
4.所有题目一律使用现行规范汉语言文字作答，未按要求作答的不得分。
5.监考人员宣布考试开始后，考生方可答题。监考人员宣布考试结束时，考生应立即停止作答，将题本、答题卡和草稿纸都翻过来留在桌上，待监考人员确认数量无误、允许离开后，方可离开考场。
严禁折叠答题卡!
二、给定材料');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (33, 2, '材料2', '1.阳光伴随着讨价还价声，洒在谷底开阔的地方，这里正是小谷村集市所在的地点。驻村第一书记汪杰正在摊前拉话时，镇长陈青松打来了电话：“不错呀，你这‘无中生有’的集市渐成气候了。”
集市上，来的人越来越多，大家一边赶集，一边说着过去种种，十分感慨:“想过有改变，但没想到会有这么大的改变。”
从前的小谷村是什么样子呢？
汪杰记得他刚来小谷村的场景。因为山多平地少，村民择坡而居，住的都是篱笆屋。住得远的村民到村委会要走两个多小时，除了出山买必要的生活用品，几乎与世隔绝。
汪杰刚到村里时，老百姓看到他，都躲得远远的。他走进住在深山的赵贵家，看到他们家高高低低四个孩子，全都没有上学，最大的孩子都十四岁了。赵贵说，女孩子就应该在家照顾猪鸡羊。男孩子呢？赵贵说，上学太远也太苦了。汪杰说，小谷村会好起来的。赵贵只是笑。
很快，在国家政策的扶持下，小谷村的各项改造开始逐步推进。从县城到小谷村的苏民路正式动工，村内七条道路的拓宽硬化同步进行，五个易地住房安置集中点建设同时启动，安全饮水配套工程加快实施，电信宽带也进入村民家中。
改变小谷村硬件容易，但是人们的思想呢？连村干部们都得过且过。汪杰来的第4天才见到他们。汪杰没有说什么，只是默默做事。他“化缘”来几台电脑，让村干部们学会打字，带领他们学习习近平总书记在解决“两不愁三保障”突出问题座谈会上的讲话，组织大家一起交流心得体会。他还有意识地锻炼年轻村干部，鼓励他们独立去解决问题。村纪检小组长刘波年轻，有些怕事，邻村一只狗咬死小谷村的一只羊，两村村民争吵起来，刘波觉得这事超出了纪检小组长能管的范围，他解决不了。汪杰鼓励刘波，村干部样样事都得会干，越复杂的事越不能往后退，并指导他具体怎么做。刘波大着胆子处理好了这件事，觉得自己以后干工作更有底气了。现在，村里到处都能看到村干部的身影，或在走访解决问题，或在填路上的积洼，或在调解邻里纠纷。汪杰戏说，他们是村里的“施工队”。
孩子是小谷村的将来，要变，不能落下他们。那天从赵贵家出来，汪杰就下了这个决心。他开始奔波，提议筹办专为大龄失学儿童提供义务教育的“桐华班”。筹办还算顺利，“桐华班”由县教育局牵头，集中县里的优秀老师，加上一些知名高校的学生志愿者，自己编写教材，精心安排课程。学生们初来时，有的还哭哭啼啼的，汪杰对他们就像对自己的孩子，给他们爱与鼓励。
可是，汪杰找来找去，发现学生里面没有赵贵的大女儿。他去赵贵家做工作，赵贵就是不同意大女儿上学。一个深夜，汪杰跑去镇上找陈青松商量，最终他们决定换个方式——送法上门。第二天，汪杰带着司法所工作人员去了赵贵家，工作人员告诉赵贵，他这样做违反了义务教育法，并苦口婆心陈述其中利害。赵贵终于同意大女儿去上学。“做人的工作也许不像修房修路那样起眼，但最根本，也最管长远，哪怕我们暂时看不到结果，也必须全力去做。”汪杰记得和陈青松探讨的那个深夜，离别时，陈青松说了这番话，并按着他的肩说:“夜色难免黑凉，前行必有曙光。”
曙光里，新修的苏民路冲开群山，伸进小谷村的谷底，村民们也搬进了新家。村里的孩子在“桐华班”学习后，渐渐有了明确的方向，他们想着继续读初中、高中，还要考大学。想到未来的生活，他们的脸上焕发着光彩，看向远方的目光更加坚定。
只有付出过，才知道其中艰难。汪杰希望自己离开后，小谷村能有东西永远留下来。同在一个镇，柏香村做茶园、搞旅游，后池村有苗圃基地。小谷村做什么呢？汪杰把小谷村的事捧在手里，掂来掂去，突然有了一个主意：在小谷村造一个集市。
经过一番努力，5月1日，大集热热闹闹开张了。汪杰到处吆喝，逢人宣传，他坚信只要坚持几个月，一定会有一个稳定、成规模、可持续的小谷村集市。汪杰做了两手准备，先是成立了村合作社，搞了小谷村集市专卖，然后告诉村民，哪怕拿鸡蛋来卖，合作社都收。同时，汪杰去镇里动员商户来小谷村做买卖。刚开始，商户们听到要去小谷村，满腹怀疑，他们印象中的小谷村是个鸟不拉屎的地方。加汪杰坚信，生活总要柴米油盐，吃穿总要必需品，只要坚持下去，集市会越来越热闹，他们自然就来了。果然，两个月后，商户们看到小谷村的集市热闹非凡，主动来找汪杰，要在集市上做买卖。
小谷村的集市越来越有模有样，汪杰又开始谋划新的出路。一个由土地、稻穗、绿叶、白云和火把组成的小谷村Logo产生了。汪杰想在村里建一个老川茶制茶厂，与大茶户合营，聘请有经验的制茶师，让山中那些野生老茶树的茶叶打上小谷村的Logo后，可以不出村就能卖到茶客的手里，也让小谷村的Logo能够深入到他们的心里。他还在想方设法加快建设标准化的养殖厂，让“走的是神仙路、喝的是山泉水、吃的是神仙草”的小谷村生态羊走向城市餐桌。
勤劳致富之风在小谷村慢慢形成，汪杰掩饰不住地高兴。他想，这些努力和奋斗所换来的，有形的会老去，无形的却能从此改变小谷村。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (33, 3, '材料3', '2.“李总监，您好，我是芯谷产业功能区项目投资科的小罗，从今天开始，我就是你们公司的项目专员，以后有什么问题您都可以找我。”W光学有限公司总务部总监李晓枫接到小罗的电话时，既意外又暖心。
近期，S市进行了“局区合一”改革，小罗的岗位，也从芯谷产业功能区规划建设部职员变成了项目投资科专员。小罗所在的项目投资科有二三十人，在一个开敞办公室集中办公。坐在她斜对面的是部门首席，他原来是芯谷产业功能区规划建设部部长，坐在她旁边的是原市发改局政策法规科的工作人员。
“改革之后，我们探索了‘首席+专员’岗位设置方式，减少了管理层级。现在有问题您提出来，我可以和大家直接沟通交流，问题会很快得到解决的。”小罗进一步跟李晓枫说。
时光转到一年前。那时候，W光学有限公司刚刚跟市政府签订协议，投资5.2亿元建设新基地，落在芯谷产业功能区。李晓枫负责新基地项目建设。
“基地建设涉及很多专业事项，对标高啊、航空限高啊，我都一头雾水。”李晓枫说，“项目需要更新坐标系，我咨询功能区管委会，被告知要去自然资源局。去了之后，发现还要再去找测绘队。申报一个事项要跑很多部门。最后我招了5个办事员，专门负责到各部门跑材料。办事员告诉我，由于不清楚办事流程，他们要一次次到管委会咨询，工作人员态度特别好，就是解决不了问题，只能当信息的‘二传手’。”李晓枫想起往事，皱起眉头。
可是现在呢，李晓枫很快跟小罗敲定了一场设计交流会。房子的外形、色彩、标高有什么要求，大门怎么开，道路怎么建，水电气的接点在哪，申报手续怎么办……40分钟时间里，有关新基地建设设计问题，相关部门都一一作了解答。这个效率让李晓枫倍感惊讶:“感觉‘二传手’一下子变身为‘主攻手’了。”
S市某领导：“我们要想改变过去产业功能区‘协调办’‘二传手’的角色，就要解决产业功能区职能太弱、功能不齐备的问题。因此，我们要思考，如何发挥产业功能区对主导产业的支撑保障？如何给产业功能区赋能？”
最终的答卷是“局区合一”改革，也就是把市政府职能部门和产业功能区管理机构整合到一起。
S市首先把发改局、航空经济局等与产业功能区关联度最高的市级部门作为主体局，通过与功能区管委会合署办公，实现整体职能覆盖功能区。目前，S市发改局的职能定位与芯谷产业功能区的建设阶段特征相契合，与城市发展、产业发展、项目落地等事宜联系最紧密。改革后，S市发改局黄局长多了两个职务：芯谷产业功能区管委会主任、党工委书记，办公地点也由S市的机关大院搬到了管委会。“我们按照‘局区合一’改革的要求，把‘两个班子、两套人员’变为‘一个班子、一套人员’。”黄局长介绍，目前发改局和管委会在事项申报、项目促建、招商引资等方面已实现职能整合，可以更好地聚焦企业服务和经济发展。
与此同时，S市把行政审批局、自然资源局、住建交通局、生态环境局等与产业功能区发展要素保障紧密相关的部门作为职能局，通过设立园区服务机构，实现核心职能下沉功能区；文体旅游局、国资金融局、人社局、教育局等部门作为事项局，通过设立投资促进机构，实现涉企服务职能延伸功能区。
黄局长介绍，“局区合一”改革后，市发改局和功能区管委会合并，原来的21个下设机构调整为6个：同时，精准定风岗定责，探索“首席+专员”岗位设置方式，形成了管理运行新格局。“我们希望以组织织再造促进流程再造，以内部放权推动整体赋能。”
目前，174项涉企市级部门审批服务事项已全部下沉功能区办理，一般性企业开办时间由20天压减至0.5天，建设项目开工前审批时间从197天压减至60天。产业功能区的资源也得到有效整合，产业规模加速壮大。2019年，己有17个项目建成投运，42个项目正在加快建设中，航空经济、电子信息、生物产业三大主导产业规模近2000亿元。
“我们的改革，没有局限于简单的修修补补，也不是机械的‘头痛医头’。我们敢于直面根本问题，深入了解基层需求，通过创新体制机制，激发企业内生动力。现在来看，我们的改革之所以成功，离不开务实的精神和理性的思考。唯有如此，才能充分发挥理论和制度的效能，实现预期目标。”黄局长如此总结。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (33, 4, '材料4', '3，“小李，我跟你说，修志工作有三苦哇!清苦，辛苦，艰苦。做地方志工作，你必须受得了这些苦:”F市地方志办公室编纂处副处长杨洋向刚到处里工作的小李再三叮嘱道。
“我搞地方志工作整整23年了，来这里工作，就要习惯坐‘冷板凳’!”老同志王建也如此教导小李。
半年后，小李依然有些疑惑：“只有加深对历史的掌握和理解，才能鉴古知今。地方志中充满了中国传统文化的智慧，对现代社会治理大有裨益。我们为什么不走出去，而只是躲在屋里修志编志呢？”
小李的问题引起了处长林德深深的思考，他准备在处里开一个讨论会，让大家谈谈地方志编纂工作的“冷与热”。
讨论会开得很热烈。
王建抢先说：“我觉得地方志的编纂工作是外冷内热。内热，就是指价值高。习近平总书记曾经说过，了解历史的可靠的方法就是看志，这是他的一个习惯。无论走到哪里，他总是要看地方志。我们可以看到，在正定、厦门、上海工作时，都留下他读志、用志的佳话，他还把地方志运用到调研工作中。我们的地方志编纂工作能为经济社会发展提供参考，你说这编纂工作重要不重要？当然，编纂工作是辛苦的，需要清心静欲，耐得住冷清。”
杨洋说:“我赞同。地方志工作看似没有地位，但只要修志者有‘为’，就一定会有‘位’；地方志部门虽然是‘冷线’，但只要干好了，也会成为‘热线’。地方志有存史、育人和资政的功能。做存史工作时，我们要沉得下心；做育人工作时，我们还得走出去；做资政工作时，我们要能摆正自己的位置。”
王建表示同意:“存史需要冷，存史才是我们地方志编纂工作最主要的功能啊！我们自己能感受到工作的成就感就可以了。没必要在乎冷热之分。”
林德说：“存史是基本功能，育人、资政是现实功能。存史，我们也可以想想，我们要记录和保存什么的历史?比如，是不是能记录咱们F市干部群众创新创业、建设美丽家乡的业绩，来以‘冷’存‘热’呢？”
王建说：“跟时代贴合、记录当下工作，确实是我们地方志编纂的重要内容，比如，今年新冠疫情突发，我们应该做好疫情防控大事记的编纂工作。”
林德说：“这个建议非常好，疫情防控大事记的编纂工作，这是存史的功能，但从另一个角度说，这是不是也有育人、资政的功能呢？”
王建听了若有所思。
杨洋接话说:“在修志存史时，如果多结合育人、资政的应用功能，我们修志的视野应该会更广阔，也应该能创造更多的机会走出去，更好地服务社会。”
王建说:“我接着说疫情防控大事记的编纂工作，这个工作我可以负责做，我们需要把市里的各项决策部署工作全面记录下来。”
林德补充说:“除此以外，我们要征集一下全市党员干部在疫情防控工作中的典型案例和先进事迹，聚焦实录全市各界在此次抗疫中不惧艰险、无私奉献的感动瞬间。”
小李说:“这个工作带着我一起做吧。另外，我觉得，在记录历史、风土人情方面，我们编纂了很多高质量的志书。但是，是不是可以形式更生动活泼一点，让老百姓也爱读呢？比如，针对儿童和青少年群体，开发一些介绍我市风土人情的课程。”
杨洋说:“咱们有很好的史料基础，如果我们能选一些有影响力的人物，以人物故事的形式出版成书，应该也会受大家欢迎”
林德说:“杨洋和小李，你们找时间把风土人情课程和人物故事书籍的建议，形成工作方案，我看是可以做的。”
王建坦诚地说:“我之前一直觉得我们把编纂工作做好就可以，今天大家的讨论给了我很多启发，走出去，也可以更好地宣传我们的修志成果，这是相辅相成的，而且啊，能把冷变热了。”
林德说:“‘以古人之规矩，开自己之生面’，是我们挖掘、梳理和萃取中华传统文化思想精华的目标方向。我们需要以积极姿态，让中华优秀传统文化价值向当代转化。这就要求我们转变工作理念和思路，对已有的工作形式进行拓展，这样就把冷门工作做热了。对了，大家对发挥资政功能有什么好的建议吗？”
小李说：“我读书时，看到地方志提供了很多有价值的资料，当时就非常兴奋。比如说地处山区的千阳县，水土流失严重，土地瘠薄。但是根据志书的描述，古时候这个地方林木茂盛，土地肥沃，宋代曾将它划为牧马良区。清朝以后，山坡被垦殖，森林减少，千阳县才逐渐变成了穷山区。地方志中还有当地种桑养蚕的记录。千阳县就参考这些记载，决定以种草植树、发展多种经营来重新振兴山区经济，并且将种桑养蚕列为其中一个重要项目。所以，要是我们的编志修志工作也能提供这种经济建设方面的资政功能，也是不辱使命了。”
王建开口说：“关于资政功能，关键还是在于咱们能体现出智库作用。咱们要根据地方志资料，结合经济社会生活重大课题，加强调研，为市委市政府提供有价值的资政材料。”
林德说：“今天的讨论很有意义。老王，你先列一些重大课题，回头咱们再集体讨论一下。”');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (33, 5, '材料5', '4.以下是《江城日报》即将发表的一篇报道：
在江城博物院，有一个专门为视障人士等特殊群体设计的博爱馆。原材料同比例复制的文物、可以操作体验的展品、首部用于视障和行走障碍观众的全自动导览车……
“除了桌子上，扶手上可以触摸到的盲文之外，我印象比较深的展品，有设计精巧的铜牛灯、长着翅膀的青瓷羊，还有脖子上戴着项圈的金兽。”去年11月，江城市盲人学校组织师生到博物院参观。虽然时间已经过去了近一年，但高二学生孙飞还记得来这里参观的感觉。在孙飞的印象中，博物院的镇馆之宝之一——汉代铜牛灯展品不仅摸起来感觉造型独特，而且还可以拆卸、旋转，更有一根长长的管子来搜集点燃油脂后产生的烟雾，形成闭环系统。他很兴奋：“这个设计在古代是‘高科技环保型’的，我们都很惊奇。”在铜牛灯仿制品前，学生们亲手触摸的同时，语音播放器也被触发，开始播放展品的介绍，而旁边的“盲文点显器”则可以介绍这件文物的历史背景、构造功能等信息。该校尹老师说：“此前也去过其他博物馆，由于缺乏有针对性的介绍，同学们感觉索然无味。但一到博爱馆，大家就对这种可听、可摸、可操作的参观体验兴趣十足。专设这个博爱馆，特殊群体可以有尊严、自主地参观展览，说明文化为民理念逐步辐射到不同人群，起了很好的示范作用。”
在展厅的不同区域，展品类型、现场布置、光线明暗等均有所不同。在弱视区和怕光区，展品以书画为主，观众可以扶着护栏，贴近细看。当有人经过书画前，语音讲解就会自动播放，每幅画还有一小段盲文介绍；在全盲区，展品则以造型类文物仿制品为主，观众在触摸展品时，也能同步听到讲解词
江城博物院藏有60余万件文物，博爱馆展厅中展示了其中按照1:1的比例、以真实材料复制的40多件展品。为何选中这40多件?博物院信息部张主任说，考虑到不同年龄层次、知识背景、兴趣爱好的观众需求，博物院从不同门类、不同材质的馆藏珍品中反复比较，经过多轮筛选和残障志愿者的测试，最终保留下他们印象最深刻、最喜爱的展品，设计出一个特殊的综合展览。“我们不以珍贵程度作为首要因素，更重要的是要让特殊人群方便解读。”策展人李婧进一步解释，展品不仅要代表江城博物院深厚的文化底蕴，也要与现代生活有关联、能想象、可互动。对于书画类展品，需要轮廓形态清楚、色彩对比强烈、故事性相对突出，让弱视群体方便观看且有代入感。对于造型类展品，造型上要有特点、纹饰要清晰、用途要体现实用性。在制作中，没有使用成本较低的3D打印，而是采用与文物相同材质的复制品，从而保证获得原材质的触感，“要让手指的叩击声也保持一致”。
不仅如此，博爱馆在设计理念方面还体现出许多贴心的细节。位置选择上，博爱馆位于一层，避开人群拥挤的主入口，降低了声音对信息获得的干扰。采光上，展馆采用玻璃顶，并安装了多个射灯，光线更通透明亮，可满足弱视群体需要。在馆内，盲道铺设的路线规划更加清晰。高低两层扶手上的盲文，在介绍展品的同时兼具引导功能。此外，江城博物院还研制了全国博物馆中首部用于视障和行走障碍观众的全自动导览车。车载计算机控制车辆前进的路径和展示点，可前行、倒退、拐弯、避让，到达展示点后自动触发感应装置，播放展品的讲解语音。
博物院不断深化服务意识，建立了意见反馈机制，认真听取参观者的建议并积极加以改善。博物院馆藏的“金兽”是国宝级文物，模样似虎类豹像狮，究竟是什么动物至今没有结论。几位视障学生对如何通过触摸理解“金兽”讲出了自己的困惑：“语音讲解上说，这个猛兽很温顺，该怎么理解呢？”这使李婧意识到，尽管采纳了很多专业建议，但依然存在“用明眼人的视角来办无障碍展览”的问题。经过对意见的研判和进一步调整设计策划，在介绍猛兽的温顺时，针对听障观众，扫描二维码可观看手语讲解视频。针对视障观众，除语音讲解和盲文介绍外，提示观众可以摸一下脖颈上的项圈，告诉他们这是被驯养的动物。
李婧说：“要改变以视觉为中心的参观感受，带给观众更丰富的感官体验，工作上还应当有更多更细致的换位思考，虽然要求高了，但能看到孩子们纯真的笑脸，我也感到很快乐。”');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (33, 3, '三、作答要求', 0, 0, '三、参考答案(H)
1.“冷”是指编纂工作清苦辛苦艰苦，工作氛围冷清，不被大众所了解和重视，比较冷门，需要工作人员耐得住寂寞。“热”是指地方志的价值高，能为经济社会发展提供参考，也指编纂工作被大众熟悉和欢迎。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (33, 1, '1、“给定材料1”中说，“这些努力和奋斗所换来的，有形的会老去，无形的却能从此改变小谷村。”请你根据“给定资料1”，谈谈对这句话的理解。（15分）
要求：分析全面，条理清晰。不超过300字。', 15, 300, '一、背景：市政府与企业签订协议并投资建设基地，但产业功能区职能弱、功能不齐备。
二、措施：（一）整合政府职能部门和功能区管理机构。1.关联度最高的部门作为主体局与功能区管委会合署办公。2.与要素保障相关的部门作为职能局，设立园区服务机构。3.事项局设立投资促进机构。（二）探索“首席+专员”岗位设置方式。
三、成效：实现了产业功能区整体赋能。1. 实现整体职能覆盖功能区、核心职能下沉、涉企服务职能延伸功能区。2.精简了机构，形成了管理运行新格局。3.大幅缩短企业开办和项目审批时间，整合了功能区资源，壮大了产业规模。
参考答案（F）
背景：功能区职能弱、设备不齐全，未支撑、保障、赋能主导产业。
措施：以组织再造促进流程再造，以内部放权推动整体赋能。1.构建部门与功能区联动格局。确定主体局，通过合署办公，实现整体职能覆盖功能区；确定职能局，设立园区服务机构，核心职能下沉功能区；确定事项局，设立投资促进机构，实现涉企服务职能延伸功能区。2.打破行政壁垒，创新体制机制。探索岗位设置方式，减少管理层级，精简机构，精准定岗定责。
成效：1.提高办事效率，促进沟通，有效解决问题。2.审批服务事项下沉，实现职能、资源整合，产业规模扩大。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (33, 2, '2、“给定资料2”中，S市进行了“局区合一”改革，请你概括这项改革的背景、措施和成效。（10分）
要求：全面、准确、有条理。不超过250字。', 10, 250, '2.“将冷的工作做热”需要转变工作理念和思路，对已有的工作形式进行拓展。
工作任务一：沉下心做好存史工作。措施：1.编志人员做好本职工作。要不畏辛苦，清心静欲，耐得住冷清，享受工作的成就感。2.做好选材工作。贴合时代，记录和保存重要事件。
工作任务二：走出去做好育人工作。措施：1.宣传正能量。记录重要部署，征集典型案例和先进事迹。2.形式生动化。选择百姓喜闻乐见的形式推广志书。3.注重影响力。选择有影响力的人物故事出版成书。
工作任务三：摆正位置做好资政工作。措施：注重实用价值。编纂人员发挥智库作用，根据地方志资料，结合经济社会生活重大课题，加强调研。
参考答案（F）
“冷”指：地方志编纂清苦、辛苦、艰苦，地位低，部门不受重视，需要清心静欲，耐得住冷清。“热”指：地方志编纂价值高，充满中国传统文化智慧，既能了解历史，又能促进现代社会治理、经济社会发展，有存史、育人、资政功能。
工作任务：转变理念思路，拓展工作形式，宣传修志成果，拓宽视野，以积极姿态将优秀传统文化价值向当代转化，发挥存史、育人、资政功能。具体措施：一、沉下心，做好修志存史。贴合时代，记录当地干部群众创新创业、建设美丽家乡的业绩，及疫情防控各项决策部署。二、走出去，发挥育人功能。传扬精神：征集疫情防控典型案例和先进事迹，聚焦不畏艰险、无私奉献等精神；开发新内容：以生动活泼的形式，开发风土人情课程，精选典型人物故事，编纂成书。三、正位置，发挥资政功能。发挥智库作用，记录地方经济发展史，结合重大课题，加强调研，为经济社会发展、政府工作提供参考。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (33, 3, '3、请你根据“给定资料3”，回答下列两个问题。（20分）', 20, 0, '三、参考答案(H)
1.“冷”是指编纂工作清苦辛苦艰苦，工作氛围冷清，不被大众所了解和重视，比较冷门，需要工作人员耐得住寂寞。“热”是指地方志的价值高，能为经济社会发展提供参考，也指编纂工作被大众熟悉和欢迎。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (33, 1, '1.谈谈什么是地方志编纂工作的“冷与热”。', 0, 0, '一、背景：市政府与企业签订协议并投资建设基地，但产业功能区职能弱、功能不齐备。
二、措施：（一）整合政府职能部门和功能区管理机构。1.关联度最高的部门作为主体局与功能区管委会合署办公。2.与要素保障相关的部门作为职能局，设立园区服务机构。3.事项局设立投资促进机构。（二）探索“首席+专员”岗位设置方式。
三、成效：实现了产业功能区整体赋能。1. 实现整体职能覆盖功能区、核心职能下沉、涉企服务职能延伸功能区。2.精简了机构，形成了管理运行新格局。3.大幅缩短企业开办和项目审批时间，整合了功能区资源，壮大了产业规模。
参考答案（F）
背景：功能区职能弱、设备不齐全，未支撑、保障、赋能主导产业。
措施：以组织再造促进流程再造，以内部放权推动整体赋能。1.构建部门与功能区联动格局。确定主体局，通过合署办公，实现整体职能覆盖功能区；确定职能局，设立园区服务机构，核心职能下沉功能区；确定事项局，设立投资促进机构，实现涉企服务职能延伸功能区。2.打破行政壁垒，创新体制机制。探索岗位设置方式，减少管理层级，精简机构，精准定岗定责。
成效：1.提高办事效率，促进沟通，有效解决问题。2.审批服务事项下沉，实现职能、资源整合，产业规模扩大。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (33, 2, '2.假如你是F市地方志办公室编纂处的工作人员，请根据讨论内容，按照“将冷的工作做热”的工作思路，起草该处下一步的工作要点。
要求：（1）准确全面，简明扼要，条理清晰；（2）工作要点包括工作任务及其工作措施；（3）总字数不超过400字。。', 0, 400, '2.“将冷的工作做热”需要转变工作理念和思路，对已有的工作形式进行拓展。
工作任务一：沉下心做好存史工作。措施：1.编志人员做好本职工作。要不畏辛苦，清心静欲，耐得住冷清，享受工作的成就感。2.做好选材工作。贴合时代，记录和保存重要事件。
工作任务二：走出去做好育人工作。措施：1.宣传正能量。记录重要部署，征集典型案例和先进事迹。2.形式生动化。选择百姓喜闻乐见的形式推广志书。3.注重影响力。选择有影响力的人物故事出版成书。
工作任务三：摆正位置做好资政工作。措施：注重实用价值。编纂人员发挥智库作用，根据地方志资料，结合经济社会生活重大课题，加强调研。
参考答案（F）
“冷”指：地方志编纂清苦、辛苦、艰苦，地位低，部门不受重视，需要清心静欲，耐得住冷清。“热”指：地方志编纂价值高，充满中国传统文化智慧，既能了解历史，又能促进现代社会治理、经济社会发展，有存史、育人、资政功能。
工作任务：转变理念思路，拓展工作形式，宣传修志成果，拓宽视野，以积极姿态将优秀传统文化价值向当代转化，发挥存史、育人、资政功能。具体措施：一、沉下心，做好修志存史。贴合时代，记录当地干部群众创新创业、建设美丽家乡的业绩，及疫情防控各项决策部署。二、走出去，发挥育人功能。传扬精神：征集疫情防控典型案例和先进事迹，聚焦不畏艰险、无私奉献等精神；开发新内容：以生动活泼的形式，开发风土人情课程，精选典型人物故事，编纂成书。三、正位置，发挥资政功能。发挥智库作用，记录地方经济发展史，结合重大课题，加强调研，为经济社会发展、政府工作提供参考。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (33, 4, '4、请你根据“给定材料4”，为《江城日报》即将发表的这篇报道写一则短评。（20分）
要求：（1）观点明确，简明深刻；（2）紧扣资料，重点突出；（3）有逻辑性，语言流畅；（4）不超过500字。', 20, 500, '四、参考答案（H）
可观可感 真实全面
——对《江城日报》一篇报道的短评
《江城日报》即将发表一篇介绍“江城博物院”的报道，该报道无论是内容还是形式，都堪称报道典范，而且符合新闻报道“客观真实”“公正全面”的基本要求，值得新闻工作者认真学习。
开篇点题，深谙报道精髓。作者在开篇写到“在江城博物院，有一个专门为视障人士等特殊群体设计的博爱馆”，由此句可知，此篇为介绍“江城博物院”的报道，写作手法符合新闻报道快速点题的要求。
以学生视角，展示“江城博物院”的独特之处，体现出报道的真实客观。文中有“高二学生孙飞还记得来这里参观的感觉”的内容，从学生的视角出发，从侧面描写出江城博物院的与众不同之处：提供可听、可摸、可操作的参观体验，让特殊群体可以有尊严、自主地参观展览，凸显博物院的文化为民理念。
另外，将对博物院的展示和相关工作人员的讲解相结合，为我们呈现江城博物院与现代生活融合的深厚的文化底蕴，贴心的设计理念，以及博物院为不断深化服务意识所采取的初心之举。这种结合符合新闻报道“全面”的要求。
总之，此篇报道既纲举目张，又细节生动，是一篇难能可贵的报道范本。
参考答案（F）
博爱馆，爱在“文化为民”
在江城博物馆，有一个博爱馆，专为视障人士等特殊群体设计。该场馆提升了观众的兴趣，让特殊群体有尊严、自主地参观，体现了文化为民，发挥了示范作用。
科学布置展区。不同区域展品类型、现场布置、光线明暗不同。弱视区与怕光区，以书画展为主；全盲区，以造型类仿制文物为主。
严格筛选制造展品。场馆拥有1：1比例、真实材料复制的40多件展品。结合观众需求，经过反复比较、筛选、测试，保留观众印象最深刻、最喜爱的展品；注重解读的便捷性，与现代生活有关联、能想象、可互动。
人性化设计场馆。设计理念贴心，注重细节。位置上避开人群，降低声音干扰；采光使用透明玻璃，安装射灯；馆内盲道兼具介绍产品和引导功能，提供全自动导览车。
持续性优化服务。不断深化服务意识，建立意见反馈机制，认真听取参观者的建议并积极改善。结合专业建议，对意见进行研判并调整设计策划。
博爱馆，改变了参观感受，丰富了感官体验，未来还将继续换位思考，致力于给特殊人群带去快乐。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (33, 5, '5、“给定资料1”中说，“夜色难免黑凉，前行必有曙光”，“给定资料2”中说“我们的改革之所以成功，离开不务实的精神和理性的思考”。请深入理解这两句话的含义，参考给定资料，联系实际，自拟题目，写一篇文章。（35分）
要求：（1）观点明确，见解深刻；（2）参考“给定资料”，但不拘泥于“给定资料”；（3）思路清晰，语言流畅；（4）字数1000～1200字。', 35, 0, '五、参考答案（H）
不惧改革藩篱 定迎成功曙光
改革从来不是容易的事，利益的博弈、困难的掣肘、道路的摸索，就如黑凉的夜色，让人感到冰冷和孤独，唯有坚定无畏的前进，才能坚持到成功曙光的来临。当前，我们的改革进入了深水区，而“解放思想，实事求是”就是我们改革成功的两个法宝，务实的精神让我们踏实走好眼前路，理性的思考让我们不会进入歧途。改革定会成功，只要我们有不变的信念和情怀，充分发挥理论和制度的效能，一定能够如期实现改革的目标，曙光也终将取代黑夜。
改革过程就是不断战胜困难的过程。从市场经济改革的摸着石头过河，到脱贫攻坚战役的拿着绣花针绣花，改革过程中既会出现早已预料的挫折，也会出现始料未及的麻烦，而这些困难无时不刻的在打消改革者的前进勇气。小谷村的发展之路，就让驻村第一书记汪杰一直走在解决困难的路上。村民的不理解，硬件条件的落后，村干部的畏惧后退，都成为了汪杰必须要战胜的困难，办法总比困难多，汪杰从基础设施的完善开始，从基层干部队伍的建设出发，和村干部一道，通过不断为群众解决生活问题，得到了群众的支持，最终也看到了成功的曙光，村民们搬进了新家，小谷村的集市和绿色品牌也换回了村民的笑脸和希望。千千万万个小谷村就是中国改革的缩影，见证了改革的进程，从遇到困难到战胜困难再到取得成功，这就是中国改革之路。
改革的成功需要务实的精神。务实精神是一种科学态度，精神状态、一种工作作风。对于改革来说，更具有特殊重要的意义。发展要有新思路、改革要有新突破，离不开求真务实的科学态度、精神状态、工作作风。脱离务实的精神，将会导致我们的改革，热衷于做表面文章、搞形式主义，搞形象工程。材料中S市，“局区合一”改革，就是务实精神的生动体现。S市面对产业功能区职能弱，功能不齐备的问题，发挥务实精神，进行“局区合一”改革，把政府职能部门和产业功能区机构整合在一起，不做表面文章，不搞形象工程，敢于直面问题，通过创新机制体制，激发企业内生动力，最终发挥理论和制度的效能，完成了预期目标，实现了改革的成功。可见，改革的成功离不开务实的精神。
改革的成功离不开理性的思考。理性思考不是停留在事物或现象的表面作就事论事的说明，而是一种辩证思维能力。改革中，如果缺乏理性思考，遇事盲目行动，轻言放弃，难免会在实践中碰钉子，把事情搞砸。相反，改革如果能以实践中得来的感性材料为基础，进行理性的思考，揭示出事物的本质与规律，定能成功。材料中F市在做地方志工作的时候，面对“冷与热”的问题时，没有亲言放弃，而是理性思考，认真分析。通过讨论，找到问题关键；转变工作理念和思路，对已有的工作进行拓展，最终把冷门工作做热了。把冷门工作做热的背后，就是一次成功的改革。其中的改革既有编纂方式的改革，也有内容和形式的创新。
总之，改革可能会遇到各种困难，但是只要我们不惧困难，不断前行，保持务实的精神和理性的思考，定能迎来胜利的曙光。
参考答案（F）
改革的决心与信心
“夜色难免黑凉，前行必有曙光”，的确，改革就好比走夜路，在黑暗中前行只能看到零星的光芒，然而发展中的问题只能在发展中解决，改革的道路越走前方越亮。
坚定的决心踏出了改革第一步，而“我们的改革之所以成功，离不开务实的精神和理性的思考”，一方面要直面问题，直面基层需求，实事求是、务实改革；另一方面要有科学的方法，灵活的机制，循序渐进、统筹推进。
改革首先是人的改革，观念的改革，从干部到人民，唯有思想变了，才能从根本上、长远上发生变化。“思想走在行动之前，就像闪电走在雷鸣之前一样。”要改革、要变革、要创新，思想上必须先解放，只有让思想从枷锁的禁锢中解放出来，才能在行动上敢闯敢干、敢作敢为，才能把改革事业不断推向前进。党员干部要带头改，想清楚、搞明白为什么改、怎么改，跟上时代前进的步伐，就不能怕给自己找麻烦，惦记那点私人利益。当然，改革也是人民的要求，干部思想变了，也要带动群众思想跟着改变。这是块“难啃的骨头”，需要慢慢来、反复劝，讲道理、摆事实。总之，思想是行动的先导，思想不变，改革只能寸步难行。
改革“一子落”，发展“满盘活”。在思想改革的指引下，更需要以务实的精神和理性的思考推进改革，践行改革，以早日拥抱改革的曙光。
改革需要务实的精神，从问题出发，以需求落脚，自上而下、全盘考量，综合性地解决改革中的难题。改革好不好，老百姓感受最直接、最有发言权，衡量改革好坏的标准也应该是百姓的问题能否解决。当前，有少数干部或眼皮朝上，不专注于解决实际问题，或说得多、做得少，观望多、行动少。但只喊口号不能建设社会主义，只讲理想，也不能实现民族复兴。“大人不华，君子务实”，对群众亟待解决的物质问题，我们应不断发展经济，对企业亟待破除的体制障碍，也应持续推进体制改革……如此真抓实干，美好蓝图才会实现，美好梦想才能成真。
改革还需要理性兜底，要注重工作方法的科学性与创新性，完善从组织再造、流程再造，到放权赋能的系统化机制。我们常说，工作方法决定工作效率。“一个项目跑多个部门”，李晓枫曾经的遭遇正是旧体制下行政效率低下的真实写照，这不仅让企业主体蒙受时间精力的损失，更让本地经济的发展步伐行进迟缓。“不日新者必日退”，只有不断革故，才能不断突破。为此，政府部门应当不畏既得利益受损，深化推进组织再造、流程再造，要敢于放权，减少管理层级，释放闲置岗位，让政府职能下沉到基层管理单位，给群众提供便捷通道，为企业创造营商环境，真正让治理效能实现跨越式发展。
回顾历史，改革决定了当代中国的命运；展望未来，改革更决定着民族复兴的前途命运。实践证明，改革是实现“两个一百年”奋斗目标、实现中华民族伟大复兴的关键一招，让我们立足今天、面向未来，用决心、务实、理性推动改革无止境！');
INSERT INTO shenlun_paper (id, paper_code, title, year, version, question_count) VALUES (34, '2021-ds', '2021年国家公务员考试《申论》真题（地市级）', 2021, '地市级', 6);
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (34, 1, '材料1', '1.本试题由“给定资料”和“作答要求”两部分构成。考试时限为180分钟。其中，阅读给定资料参考时限为50分钟，作答参考时限为130分钟。总分100分。
2.请在题本、答题卡、草稿纸指定位置上用黑色字迹的钢笔或签字笔填写自己的姓名和准考证号，并在答题卡上用2B铅笔将准考证号对应的数字涂黑。
3.请用黑色字迹的钢笔或签字笔在答题卡指定的答题区域内作答，超出答题区域的作答无效。
4.所有题目一律使用现行规范汉语言文字作答，未按要求作答的不得分。
5.监考人员宣布考试开始后，考生方可答题。监考人员宣布考试结束时，考生应立即停止作答，将题本、答题卡和草稿纸都翻过来留在桌上，待监考人员确认数量无误、允许离开后，方可离开考场。
严禁折叠答题卡!
二、给定材料');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (34, 2, '材料2', '1.Y县的风林村有13个村民小组，曾是一个有名的贫困村。全村总体地貌为高山峡谷，森林覆盖率高，动植物资源丰富.
过去,靠山吃山、砍树卖钱，是当地人视为天经地义的生活逻辑。由于地处山区，这里旱地多、坡地多,气候寒凉，适宜种植的经济作物种类较少，农民收入较低。“以前大家没钱了就上山去砍树卖，钱用完了又去砍，你砍、我砍、大家砍，对森林的破坏很大。“风林村村民赵春桥说。这样的生产生活方式，让风林村的生态环境遭遇了前所未有的挑战。“小时候河水大到能推动水磨，后来山泉水少了，村里吃水都困难!”风林村党支部书记周云光说，山上的树越砍越少,河里的鱼渐渐消失,不仅当地的生物多样性遭到破坏，村民的生存发展也渐成问题。“可是，吃饭需要钱，盖房子需要钱，娃娃读书需要钱，不砍树，大家的生计怎么办呢?”赵春桥说。
怎么把村民力量发动起来，既让大家吃饱穿暖，又能保护好生态?为了解决生态保护和村民生存的矛盾，2016年，当地党委和政府在风林村引入“村寨银行”项目作为新的探索:村民以小组为单位，每家自愿拿出1000元入股，和其他社会扶持资金合起来，每年发放给小组内1/3的村民用于生产生活，借贷的村民1年后连本带息还款，下一批村民继续借贷，以此方式滚动实施。村民可以自由支配这笔钱，发展种养殖业、供孩子上学、盖房、看病等，但要签订环保协议,承诺不再砍树，不再从事破坏生态环境的生产活动，违背协议者将罚没入股资金。
一开始，村民并不认可和接受。当村民听说要建“村寨银行"，以为又是扶贫项目来了，都反响热烈，但后来听说项目还需要自己出资，便开始犹豫起来。“以前我们都是各过各的，谁也不管谁，现在要集资建银行，我们哪里懂哦!”“大家的钱怎么管?往哪个方向奔?要争取哪些利益?这些事情我们可几十年都没想过。靠我们自己，能行吗?”在一个个夜晚，村民围着火塘挤在一起，七嘴八舌地讨论着。
村民不断提出疑问、发表意见，并最终讨论出一个人人都能接受的管理制度，比如:谁砍树了，除入股本金被扣除外，全村人都不参加他家的红白喜事;谁家不还贷款,他家的林权证、政府发放的农资补贴等，就要被扣留...
村民自己立规矩,效果出乎意料地好。村里因地制宜制定村规民约，村民之间也更和睦。大家-起商量垃圾怎么回收、怎么处理，“一事一议”落到了实处。几年下来，风林村环境好了,村民的心也拢在了一起，周云光干了近20年村干部，他说现在风林村“制度最管用、自治最省心”。
全村13个村民小组,都划定了自然保护地,并在村民讨论的基础上,制定了管理条例，明确了自然保护地的范围、保护措施、奖惩措施，全体村民都有权利监督落实条例的执行情况。
借贷来的资金,村民们有的用于养猪、养羊等养殖业，有的用于中药材种植，也有的用于看病就医、子女就学等方面。“村寨银行”既满足了村民在生产生活中的各种资金需求，又激发了村民保护生态的内生动力，让保护自然环境成为了一种自觉。
新房组李国坤家，家门口已搭起了五六个蜂箱，地里种上了野生菌。“全组都参加了这个项目，10户获得了首批贷款，有的种上了药材，有的买了猪羊。”李国坤介绍，全村已经没人上山砍树了。“现在，护林员不用满山跑，轻轻松松坐在家里或者干干农活儿，就能把山看管得好好的。因为，全村人的眼睛都在盯着呢!”李国坤笑着说。
不能砍树，那就种树。几年下来，风林村转变了发展方式，种植了核桃、梅子等果树，开辟了中药材生产基地，共达3400多亩。村民在山上养蜂，田里种豆，通过专业合作社把农产品销往全国，大家的腰包也越来越鼓。
随着生态越来越好，山上的金丝猴、小熊猫等珍稀动物又多了起来。越来越多的游客慕名来到风林村，村民们建客栈、开餐馆、跑运输、做向导，过好日子的劲头越来越足。
“物无妄然，必由其理。风林村因地制宜，遵循自然规律，从坐吃山空到山绿人富，走上了一条绿色发展之路。”有环境治理专家评论道，“‘村寨银行’与生态环保联动，通过对人们观念和行为方式的改变，进而影响自然的改变，最终实现人与自然关系的平衡和发展。”');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (34, 3, '材料3', '2.“曹团长今天下午又要来教戏了。”消息一大早就在新民县刘村传开了，刘桂英放下碗筷，稍做收拾，来到村头大舞台，争分夺秒练习，等待老师前来指点。
40多岁的刘桂英，从小跟着家人听戏，一不留神，从“粉丝”变成了“戏痴”。在过去，刘桂英跑遍十里八村去看戏。如今，不出村就能在家门口欣赏名家唱段了。最让她开心的是，这些名角不仅到村里唱戏，还教村民唱戏。
“过去演几场就走了，群众‘不解渴’。如今剧团开展‘结对子、育骨干’，在乡村打造一批不走的农民剧团。”新民县花鼓戏团团长曹文君说。
刘桂英不出村就能得到名师指点，得益于新民县实施的文化惠民工程。虽然仅新民县花鼓戏团每年就到乡下演出100多场，但要让戏曲在乡村扎下根，最好的办法是让群众“自娱自乐”。因此，除了政府出钱，群众看戏之外，新民县还鼓励戏曲艺术表演团体与乡村戏曲团队开展“结对子、育骨干”活动，通过“搭台子、指路子、给梯子”等方式，鼓励民间文艺团体发展，对乡村文艺人才进行传帮带，帮助他们提高创作水平和表演能力。
农民演、农民看。人称“戏窝”的刘村已经这么唱了4年，现在唱上了瘾。刘村农民花鼓戏团的演员也逐年增加，从3人到5人，最后发展到30人。
“戏曲是在民间产生的，又在民俗活动的氛围中逐步发展起来。要在乡村推广普及戏曲艺术，就要借助民间的生活礼仪，培育戏曲在乡村生存发展的文化土壤。”曹文君说，新民县花鼓戏团充分把握春节、元宵节、端午节、中秋节、重阳节等重要民俗节庆，结合民间风俗和节庆文化开展戏曲演出，老百姓非常喜欢。
怎样确保唱的戏是乡村群众欢迎的？一份《乡村演出节目单》，一份《乡村演出调查问卷》，是新民县探索让“戏”对味和受欢迎的举措。“每隔一段时间，我们会和院团沟通，制定《乡村演出节目单》下发到村里。村民从中选出最喜欢的5个，我们汇总需求后反馈给院团，他们以此安排接下来的演出。”新民县文化和旅游局副局长张学敏拿着一份调查“菜单”说，“去年县里做了3次调查，下发3000多份调查问卷。调查结果是乡村的青年观众更喜欢现代戏，而中老年观众更喜欢传统戏曲，尤其是贴近乡村生活的戏。”
“目前乡村的戏曲观众仍以老年人为主，要吸引年轻人的关注，有必要对戏曲剧目进行现代化创新。”于是，针对不同年龄段观众的不同需求。新民县花鼓戏团在乡村演出的不仅有经典的花鼓戏，还有现代戏。“我们以现代戏吸引年轻观众来现场，再演几出有趣的花鼓小戏，很快，一些人就被花鼓戏‘圈粉’了。”曹文君说，“戏曲院团也应根据乡村演出市场的规律安排自己的演出计划。既然观众需求不一样，我们就不能一成不变，所以大家花心思加入了许多现代元素。我们以进乡村为契机，采集了许多贴近乡村生活的民间故事，创排了《五朵村花》《鹅匠》等现代戏曲作品，不仅老年人喜欢，年轻人也看得津津有味。只有把戏唱在群众心坎上，才能吸引乡村观众，让戏曲在乡村真正留得下。”
每次演出前,花鼓戏团的演员都会给观众介绍一下剧目的内容、作者、创作背景等,一点一滴地为他们普及戏曲知识。对此，曹文君解释道:“除了要为乡村观众唱好戏，我们还要培养乡村观众，让他们了解戏曲、认识戏曲、喜欢戏曲。”
盛夏的一天，花鼓戏排练厅的温度接近40摄氏度，15岁的婷婷和20多个同龄的孩子，还在这里集中训练。他们是花鼓戏团与新民县职业高级中学联合创办的戏曲表演班的第一期学生。经过近一年的学习,婷婷的一招一式已经颇有味道。听说要经常下农村演出，很辛苦，她不假思索地说:“我们本来都是农村里的孩子，所以去农村演出就是回家，并不会觉得辛苦。”“从乡村挖掘有潜力的孩子加以培养，以后再反哺乡村，乡村的戏曲才能得以持续。”曹文君说道。
“我们不仅仅是为乡村群众唱几场戏，更重要的是要‘种戏’。”张学敏说，“戏曲生长在民间、活跃在民间、变革在民间。戏曲的生存与发展有其自身的规律，只有回归民间，回归群众，才能在乡村留得住、传得开、唱得响。”');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (34, 4, '材料4', '3.冬日，石板街道清河社区，66岁的姚叔在亲水平台上的茶座里招待客人。
清河社区就在清河岸边，是H市最古老的街区之一。姚叔小时候，最喜欢的就是和小伙伴一块在清河岸边玩耍。那时候的清河，河水清澈，两三米深的地方依旧清可见底。后来随着沿岸工厂和小作坊越来越多，清河也慢慢地变成了黑臭河。
转变发生在2014年。那一年，姚叔刚好退休，也听到了许多新名词：“五水共治”“截…污纳管”“污水零直排2.0模式”……与此同时，姚叔发现，身边的清河水一天天变清了。他不知道的是，这几年来，清河社区已陆续关停50余家清河沿岸的“散乱污”小作坊。
清河水变清了，社区里清河直街的改造也在居民的关注下完成。去年夏天，姚叔想在家门口的亲水平台上开个茶座。“这个平台曾是我家老码头，后来变成堆杂物的地方，改造一下也是改善环境。”本来，由于平台性质的问题，他以为营业执照的审批特别麻烦，没想到社区认为是好事就帮他沟通，执照很快就顺利办了下来。
清河直街的长征桥头，有一家开了20年的无名面馆，如今有了“老桥头面馆”的大门匾，也成为石板街道的吃货热捧之地。改造后的清河直街，留下了这碗做了20年的面，也留下了老城的记忆。如今直街已改造到第三期，但有一点理念始终没变：清河应该是有历史积淀的。人们走到这儿，就会勾起旧时的记忆。
这样清幽的清河直街，吸引了一家家艺术气息浓厚的非遗文创工作室、传统家居生活馆、手工艺术馆……也让清河社区有了浓浓的文化气息。
沿着清河河畔一路向西，转过勤丰桥,两幢黄色的小楼分外显眼。这就是清河社区去年10月开张的“阳光老人家园”。中午，穿过塑胶铺就的大院子，步入大门，映入眼帘的是满满的文艺范：温暖的橙黄色，大大的落地窗，带落地镜的舞蹈教室……到处都洒满了阳光。
“清河社区是一个老社区，4000多常住人口中，60岁以上的退休老人有800多人，所以老人是我们的重点服务对象。”清河社区居委会主任孙鸣说，“但服务老人，不仅要满足他们的需求，更要引领他们的生活方式，让老人消除与时代的隔阂感,找到归属感、共鸣点。今后，我们还要进一步贯彻落实十九届五中全会精神，积极应对人口老龄化，不断加强和创新社会治理。”
“阳光老人家园”没有麻将桌，但有各种兴趣小组,可以三五个好友聚在一起吹拉弹唱，也可以老伙伴们在乒乓球桌前来一场较量。让老人像孩子一样，有自己的兴趣班，这是清河“阳光老人家园”设计的重点。为此，这里设有活动室、多功能厅、书画教室、化妆间、社会组织办公室等功能区，还排有相关课程，由专业老师来定期教学。
社区卫生站也搬到了“阳光老人家园”旁边。挂号配药、简单诊治等服务全部涵盖，医保卡功能也全部开通，成了百姓家门口的医院。
幸福街是清河社区的一条商业街，水果摊主李海明，正把门口的泡沫箱扛起来，放回店内，又拎起拖把，把地面认真拖了一遍。
很难想象，李海明以前是个“一点就爆”的“火药桶”。他时常把水果堆到人行道上，一有城管来批评他，他就扯着喉咙开吵。
李海明的转变，得从“城市眼”的引入说起。
去年10月，清河社区试着引入“城市眼”管理模式。该模式通过接入高清探头，对重点区域进行全天候监控。这只“城市眼”不但看得见，更能看得懂。通过后台对比识别，探头可对出店经营、垃圾堆放、沿街晾晒、游商经营等违规行为和不文明现象进行识别，并将相关信息实时发送至后台。
以前靠人工采集，一个月仅能发现100多起违规行为，而最初装上“城市眼”的那个月，就发现了500多起，如此大的值息量怎样处理？孙鸣拿出手机，打开微信，展示了清河社区的管理工作群，相关商家、社工、城管工作人员都在群里。当“城市眼”后台将违规行为信息发送至相关社工手机上时，社工第一时间发到微信群，并让商家整改。社区进行监督，城管再最后兜底。为让商家更主动，社区还成立自治管理委员会，李海明就是成员之一。
“也奇怪，成为自治管理委员会成员后，他就通情达理了很多。”孙鸣笑着说，“几乎不用我们督促自己就能管好。”
“以前一上来就说我这不对那不对当然要吵。”李海明说，被选入自治管理委员会后，他常去社区开会，“他们说店里太乱容易引发火灾，环境变差最终影响的还是店里客流，我听了以后觉得是这么回事，回来就改了”。
社区里的事情，大家商量着办，反而更容易推进和实现，这是清河社区摸索出来的一个道理。
今年年初，清河社区年代久远的安置房小区—广明新村将迎来第一场“微更新”，工程启动在即，孙鸣却说：“我们先听听居民意见。”
在广明新村10幢，62岁居民沈祖岩向80后社工方颖细细道来：“最好是拆迁。不行的话，装电梯、换雨棚、换下水道也是好的。小区停车太难，女儿开车过来吃个饭，一不小心就会被贴罚单，最好腾挪出点车位。”方颖颖拿着个小本本记录了下来。出门时，她握着沈祖岩的手说：“大伯您放心好了，我都记下了，改造时我们一定会参考的。”
清河这个老社区，伴随着静静流淌的河水，在不动声色中蜕变，滋长出绵长的生命力。居民们都说：“社区越来越美了。”“只要我们用心给这片土地最大的温暖，慢慢地，它就会越来越美。这，就是清河故事所折射出的治理之道。”石板街道负责人说。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (34, 5, '材料5', '4.Z市晚报策划了“城市出行”专题系列报道，本期聚焦”人行道”问题。以下是记者的调查报道：
下午5时许，盲人郑志涛手拿着一根盲杖，不停地左右敲打前方路面，沿正七街行走在机动车道上。
机动车道上车流汹涌，郑志涛为什么不走人行道?他有自己的理由。
郑志涛说，去年10月的一天，他在西开发区崇武街人行道上行走，他认为自己是走在盲道上，走的速度就很快，没料到，竟一头撞在了一棵大树上。从此以后，凡是外出,郑志涛再也不愿走人行道了，“还不如走机动车道，顺着马路牙子走，不会撞到树”。
记者进行了调查，发现正六街、丰产路、南七路、南九路等路段的人行道,有些地方被大树挡道，而且树木根系发达，裸露在外，行人一不小心就会被绊倒。“南七路人行道两侧的杨树最碍事，人行道只有两米多宽，大树就占了一半。”市民李先生说。
除了树木挤占,人行道上窖井盖凸出或凹陷,电表箱随意设置等,也影响行人通行。记者走访时,发现一些人行道边上的电表箱离地面不足1.5米,有些电表箱的门还是敞开的，行人走路经过时，稍不留意就会被碰到。“这些问题涉及到多个部门,我们与相关单位也协商过，但收效甚微。”Z市公安局交警支队的负责人说。
记者行至泉水路时,发现眼前的道路突然“断头”了，整个人行道都被工地围挡圈上封锁，周围也没有交通警示和疏导。在施工现场东侧入口前的人行道上,长约百余米的路面堆满了施工用的建筑材料。不仅如此，还有几位工人蹲在人行道上对建筑材料进行焊接,俨然把道路当成了施工现场。“这个建筑工地向北不足200米就是一所小学，这条道路就是家长接送孩子上下学的必经之路，现在人行道被占用，我们只能绕到机动车道上，加上又有很多大型运输车辆途经此处，真是太危险了!”市民刘先生说。一位急着送孩子去上学的家长也抱怨道：“去学校只有这一条路，现在人行道都被挡死了，一点空间都不留，这不逼着我们往马路上走吗?”
记者调查发现，占道施工阻碍行人通行的现象在不少路段都存在。西中街人行道正在改造施工，两侧路面已被挖开,裸露在外的是干燥的尘土路面。环卫工人正在清扫路面，顿时扬起一阵尘土，并迅速扩散到方圆十来米，行人路过不禁皱着眉头，捂住囗鼻。市民李女士说：“这个施工已经快半年了，怎么还没结束？有时候看他们根本没在施工，这样磨洋工，什么时候能结束呀？”另一位市民王先生则说：“人行道改造施工是好事，但为什么要两边同时开挖呢？我们都不知道路在哪里了。”
常六路的一栋商务楼门前，不少自行车和电动车杂乱无章地停放在人行道上。“这边的人行道本来就窄，被自行车和电动车占用后，行人通过非常困难，有些人索性走到了非机动车道上，很不安全。”市民杜先生说。“这里没有明显的禁停标志，周围也没有其他可以停放电动车的地方，为图方便，我就将车停在这儿了。”市民韩先生说。记者发现，商场、写字楼、地铁出入囗等人流密集的公共场所，附近的人行道被非机动车占用的情况普遍存在。
记者前往多个路段探访，发现除了非机动车占道外，很多维修摊点也把生意做到了人行道上。在体育大街的人行道上，有配钥匙的，也有修自行车的，很是热闹·维修摊点地面上堆放着轮胎、马扎、砖头、木箱子，狼藉一片。
记者又来到金水路，中原路等路段，发现这些路段没有非机动车道，不少非机动车都开上了人行道。人车混行的现象较为严重，也导致不少事故发生。
“电动车速度太快了，走在路上胆战心惊的。”习惯步行上班的徐女士说，她走路时总是尽量靠右，但有一次还是被电动车挂了一下，差点受伤。
报道结语：人行道是城市重要的基础设施。只有不断更新和提升对城市运行规律的认识，真正从人行道的本质功能出发，统筹做好建设和管理，才能保障行人的通行权益，让行人在人行道上惬意行走。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (34, 3, '三、作答要求', 0, 0, '三、参考答案（H）
清河社区的治理之道
各位领导、同事：
大家好！很荣幸能够代表石板街道参加此次座谈会。我们街道的清河社区在清河岸边，是H市最古老的街区之一。这几年清河社区变得越来越美，主要得益于如下治理之道：
一、改造社区，改善环境。陆续关停多家清河沿岸的“散乱污”小作坊，告别黑臭河；帮助居民把废旧老码头改造为茶座，变废为宝；保留有历史积淀的商铺，营造浓厚文化气息。
二、以人为本，完善服务。满足老人需求，引领老人生活方式，为老人找到时代归属感。如建设配有兴趣班、多种功能区等的“阳光老人家园”；社区卫生站就近为老人提供挂号配药、简单诊治等全覆盖的服务。
三、应用科技，共商共治。引入“城市眼”管理模式，对重点区域进行全天候监控，对违规行为和不文明现象进行识别，并将相关信息实时发送至后台；建立包含商家、社工和城管的管理工作群，成立自治管理委员会，共同监督、督促商家整改；社区更新注重倾听收集民意。
以上就是我的发言，谢谢大家！
参考答案（F）
清河社区的治理之道
为贯彻落实十九届五中全会精神，加强和创新社会治理，清河社区打造水美宜居、老有所乐、和谐民主的社区。
一、进行街道治理。1.治理清河污染，采取“五水共治”等新手段，关停“散乱污”工厂。2.进行房屋功能改造，增加商业价值，改善居住环境，社区帮助沟通，加速证照审批。3.打造老字号品牌，保留城市记忆；吸引文创产业入驻，营造浓厚文化气息。二、开办“阳光老人家园”。1.满足老人日常需求。完善基础居住设施，就近设置社区卫生站，涵盖基础医疗服务，同步医保功能，方便就医。2.引领生活方式，组建兴趣班，丰富娱乐文化生活，增设多功能区，配备相关课程，聘请专业老师定期教学，帮助老人找到归属感和共鸣点。三、引入“城市眼”管理模式。1.接入高清探头，全天候监控重点区域，识别违规行为和不文明现象，实时发送信息至监控后台。2.组建管理工作群，社工及时反馈违规信息，督促商家整改，城管兜底，保障效果。3.成立自治管理委员会。引导商户参与，激发自觉性；进行社区民主治理，听取意见，满足诉求。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (34, 1, '1、“给定资料1”中，风林村在实施“村寨银行”项目后，发生了巨大变化。请你谈谈风林村有了哪些变化。（10分）
要求：全面、准确、有条理，不超过250字。', 10, 250, '1.针对缺少盲道等无障碍道路问题，建议设置盲道，扫清盲道障碍物，保证特殊人群正常通行。
2.针对大树挡道，井盖、电表箱随意设置问题，建议与相关单位统一协商，移植占道树木，保障井盖与路面保持平整，高度一致，电表箱调高安装高度，并上锁管理。
3.针对长时间占道施工，安全隐患大，导致无路可走问题，建议科学施工，施工时留临时通道，禁止两头开挖，加强交通疏导，保证有路可走；规范施工，设提示牌，禁止露天操作，划定区域堆放建筑材料，保障施工安全和环境清洁；提高施工效率，缩短施工时间。
4.针对非机动车占道、经营占道问题，建议设立非机动车停车点，有序停放，加大非机动车乱停放的惩罚力度；设置固定经营摊位，划定货物门前摆放的禁止线，加大对于占道经营的管理力度。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (34, 2, '2、“给定资料2”中说：“我们不仅仅是为乡村群众唱几场戏，更重要的是要‘种戏’”。请你根据“给定资料2”，谈谈对“种戏”的理解（15分）
要求：分析全面，条理清晰。不超过300字。', 15, 300, '二、参考答案（H）
“种戏”是指借助民间的生活礼仪，通过培育戏曲在乡村生存发展的文化土壤，让戏曲生长在民间、活跃在民间、变革在民间，在乡村扎下根。
因为相比为乡村唱戏，“种戏”才能真正满足群众对戏曲的需求，有助于民间戏曲团体的持续发展，使戏曲在乡村留得住、传得开、唱得响。
实现“种戏”的对策有：1.实施文化惠民工程，鼓励戏曲艺术团体与乡村戏曲团队开展“结对子、育骨干”活动，鼓励民间艺术团体发展，对乡村文艺人才传帮带，提高其创作水平和表演能力。2.采集贴近乡村生活的民间故事，创新戏曲剧目。演出前普及戏曲知识，培养乡村观众，让其了解戏曲、认识戏曲、喜欢戏曲。3.挖掘培养有潜力的乡村孩子，让其反哺乡村。
参考答案（F）
“种戏”是让戏曲在乡下扎根，回归民间、回归群众，在乡村留得住、传得开、唱得响。
一、发展民间文艺团体，让群众“自娱自乐”。实施文化惠民工程，鼓励专业剧团开展“结对子、育骨干”活动，进行传帮带，提高其创作水平和表演能力，壮大队伍。
二、培育文化土壤，让群众喜欢戏曲。借助民间生活礼仪，结合民间风俗和节庆文化开展戏曲演出；调查群众喜好，进行现代化创新，满足不同年龄段的群众需求；培养乡村观众，普及戏曲知识，让观众了解、认识戏曲。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (34, 3, '3、H市近期准备召开“社区治理与服务经验交流座谈会”，你作为石板街道负责人，将在座谈会上发言。请你根据“给定资料3”，以“清河社区的治理之道”为题，写一份发言提纲。（20分）
要求：(1)内容全面、具体;(2)有逻辑性,语言流畅; （3）不超过450字。', 20, 450, '三、参考答案（H）
